import { useCallback, useMemo } from 'react';
import { useSelector } from 'react-redux';
import { useRoute, useFocusEffect } from '@react-navigation/native';
import { RootState } from '../../../Auth/src/redux/store/types';
import { NavigationService } from '../services/NavigationService';
import {
  CrewParticipant,
  ParticipantStatus,
  JobDetailMode,
} from '../types/jobDetail.type';
import { SCREEN_ENUM } from '../types/global';
import { dispatch } from '../helper';
import colors from '../../../Auth/src/theme/colors';

export const useOtherCrewMembers = () => {
  const route = useRoute();
  const { scheduleActivityId, id, isLeader } = route.params as {
    scheduleActivityId: string;
    id: string;
    isLeader?: boolean;
  };

  // Redux state - now part of jobDetail
  const participantsState = useSelector(
    (state: RootState) => state.jobDetail?.participants,
  );

  const participants = useMemo(() => {
    return Array.isArray(participantsState?.data) ? participantsState.data : [];
  }, [participantsState?.data]);

  const isLoading = participantsState?.isLoading ?? false;
  const error = participantsState?.error ?? null;

  // Fetch data when screen is focused
  useFocusEffect(
    useCallback(() => {
      const fetchData = async () => {
        const redux = await import('auth/redux');
        dispatch(
          redux.actionContainer.getWorkOrderParticipantsAsync({
            scheduleActivityId,
            purchaseOrderId: id,
          }),
        );
      };
      fetchData();

      // Cleanup when screen is unfocused
      return () => {
        const cleanup = async () => {
          const redux = await import('auth/redux');
          dispatch(redux.actionContainer.clearWorkOrderParticipants());
        };
        cleanup();
      };
    }, [scheduleActivityId, id]),
  );

  // Get status color and text
  const getStatusInfo = useCallback((t: any, status: ParticipantStatus) => {
    switch (status) {
      case ParticipantStatus.Completed:
        return {
          color: colors.alertColorSuccess,
          text: t('COMPLETED'),
        };
      case ParticipantStatus.InProgress:
        return {
          color: colors.mainColorPrimary,
          text: t('IN_PROGRESS'),
        };
      case ParticipantStatus.Pending:
        return {
          color: colors.mainColorSecondary,
          text: t('PENDING'),
        };
      default:
        return {
          color: colors.mainColorSecondary,
          text: t('PENDING'),
        };
    }
  }, []);

  // Calculate progress percentage
  const getProgress = useCallback((participant: CrewParticipant) => {
    if (participant.checklistTotal === 0) return 0;
    return (participant.checklistChecked / participant.checklistTotal) * 100;
  }, []);

  // Handle go back
  const handleGoBack = useCallback(() => {
    NavigationService.goBack();
  }, []);

  // Handle participant press - navigate to participant job detail
  const handleParticipantPress = useCallback(
    (participant: CrewParticipant) => {
      NavigationService.push(SCREEN_ENUM.JobDetailScreen, {
        id: participant.id,
        scheduleActivityId: participant.scheduleActivityId,
        mode: JobDetailMode.PARTICIPANT,
        isLeader: isLeader ?? false,
      });
    },
    [isLeader],
  );

  return {
    // Data
    participants,
    isLoading,
    error,
    totalCount: participants.length,
    isLeader,

    // Helpers
    getStatusInfo,
    getProgress,

    // Actions
    handleGoBack,
    handleParticipantPress,
  };
};
