import { useEffect, useMemo, useCallback } from 'react';
import { useRoute } from '@react-navigation/native';
import { useSelector } from 'react-redux';
import { useAppTranslation } from './useAppTranslation';
import { NavigationService } from '../services/NavigationService';
import { dispatch } from '../helper';
import { logger } from '../utils';
import type { BottomSelectorOption } from 'tradewize-component';
import { generateQuantityOptions } from '../helper/jobStart.helper';
import { useState } from 'react';

// ============================================================================
// Types
// ============================================================================

interface RouteParams {
  vpoId: string;
  taskId: string;
  isNeedRefresh?: () => void;
  onGoBack?: () => void;
}

interface GroupedMaterials {
  [key: string]: any[];
}

// ============================================================================
// Hook
// ============================================================================

const useVerifyMaterialVPO = () => {
  const route = useRoute<any>();
  const { vpoId, taskId, isNeedRefresh, onGoBack } = (route.params ||
    {}) as RouteParams;
  const { t } = useAppTranslation();

  // Redux state
  const dataMaterial = useSelector(
    (state: any) => state.jobDetail?.vpoData?.data ?? [],
  );
  const isLoading = useSelector(
    (state: any) => state.jobDetail?.vpoData?.isLoading ?? false,
  );
  const isSubmitting = useSelector(
    (state: any) => state.jobDetail?.submitVpo?.isLoading ?? false,
  );

  // Bottom Selector state (local — no need for Redux)
  const [isSelectorVisible, setIsSelectorVisible] = useState(false);
  const [quantityOptions, setQuantityOptions] = useState<
    BottomSelectorOption[]
  >([]);
  const [selectedItemId, setSelectedItemId] = useState<string | null>(null);

  // ============================================================================
  // Fetch Data via Redux
  // ============================================================================

  useEffect(() => {
    const initData = async () => {
      if (!vpoId) return;
      try {
        const redux = await import('auth/redux');
        const action = redux.actionContainer.getVPODataAsync({ vpoId });
        dispatch(action);
      } catch (error) {
        logger('Error dispatching getVPODataAsync:', error);
      }
    };

    initData();

    return () => {
      // Cleanup on unmount
      const cleanup = async () => {
        try {
          const redux = await import('auth/redux');
          dispatch(redux.actionContainer.clearVPOData());
          dispatch(redux.actionContainer.hideCommentChecklistModal());
        } catch (error) {
          logger('Error dispatching cleanup:', error);
        }
      };
      cleanup();
    };
  }, [vpoId]);

  // ============================================================================
  // Grouped Materials (by materialTypeId)
  // ============================================================================

  const groupedMaterials: GroupedMaterials = useMemo(() => {
    const groups: GroupedMaterials = {};
    if (!Array.isArray(dataMaterial)) return groups;

    dataMaterial.forEach(item => {
      const typeId = item?.materialTypeId || 'unknown';
      if (!groups[typeId]) {
        groups[typeId] = [];
      }
      groups[typeId].push(item);
    });

    return groups;
  }, [dataMaterial]);

  // ============================================================================
  // Handlers
  // ============================================================================

  const getTypeName = useCallback((items: any[]): string => {
    return items?.[0]?.materialTypeName || 'Unknown Type';
  }, []);

  const openQuantitySelector = useCallback(
    (itemId: string, maxQuantity: number) => {
      setSelectedItemId(itemId);
      setQuantityOptions(generateQuantityOptions(maxQuantity));
      setIsSelectorVisible(true);
    },
    [],
  );

  const handleSelectQuantity = useCallback(
    async (option: BottomSelectorOption) => {
      if (!selectedItemId) return;
      const numericValue =
        option.value === '' ? null : parseFloat(option.value as string);

      try {
        const redux = await import('auth/redux');
        dispatch(
          redux.actionContainer.updateVPOReceived({
            id: selectedItemId,
            quantity: numericValue,
          }),
        );
      } catch (error) {
        logger('Error dispatching updateVPOReceived:', error);
      }

      setIsSelectorVisible(false);
      setSelectedItemId(null);
    },
    [selectedItemId],
  );

  // Get initial value label for BottomSelector
  const getInitialValue = useCallback(
    (item: any): string | undefined => {
      const value = item.receivedQuantity2?.toString();
      return value || undefined;
    },
    [],
  );


  // ============================================================================
  // Submit VPO
  // ============================================================================

  const validateVPO = useCallback((): boolean => {
    if (!Array.isArray(dataMaterial)) return false;
    return dataMaterial.every(item => item.receivedQuantity2 !== null);
  }, [dataMaterial]);

  const submitVPO = useCallback(async () => {
    if (isSubmitting) return;

    try {
      const redux = await import('auth/redux');

      if (!validateVPO()) {
        dispatch(
          redux.actionContainer.showAlertAsync({
            title: t('PLEASE_SELECT_ALL_RECEIVED_NUMBER'),
            visible: true,
            type: 'warning',
          }),
        );
        return;
      }

      const checklistItems = (dataMaterial || []).map((item: any) => ({
        id: item.id,
        quantity: item.receivedQuantity2,
      }));

      dispatch(
        redux.actionContainer.submitVPOAsync({
          vpoId,
          taskId,
          checklistItems,
          onSuccess: () => {
            if (isNeedRefresh && typeof isNeedRefresh === 'function') {
              isNeedRefresh();
            }
            onGoBack?.();
            NavigationService.goBack();
          },
          onError: (error: any) => {
            logger('Error submitting VPO:', error);
          },
        }),
      );
    } catch (error) {
      logger('Error dispatching submitVPOAsync:', error);
    }
  }, [isSubmitting, validateVPO, dataMaterial, vpoId, taskId, isNeedRefresh, onGoBack, t]);

  // ============================================================================
  // Navigation
  // ============================================================================

  const handleGoBack = useCallback(() => {
    onGoBack?.();
    NavigationService.goBack();
  }, [onGoBack]);

  return {
    // Data
    dataMaterial,
    groupedMaterials,
    isLoading,
    isSubmitting,

    // Actions
    getTypeName,
    submitVPO,
    handleGoBack,
    getInitialValue,

    // Bottom Selector
    isSelectorVisible,
    quantityOptions,
    setIsSelectorVisible,
    openQuantitySelector,
    handleSelectQuantity,
  };
};

export default useVerifyMaterialVPO;
