import { View } from 'react-native';
import React, { useState } from 'react';
import { styles } from './styles';
import {
  Button,
  WheelDatePicker,
  SCREEN_WIDTH,
  Text,
  Input,
  BottomSelectorOption,
} from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import {
  IconCalendar,
  IconChevronDown,
  IconChevronRight,
} from '../../../../assets/svg';
import { colors } from '../../../../theme';
import { useAppTranslation } from '../../../../hooks/useAppTranslation';
import dayjs from 'dayjs';
import { NavigationService } from '../../../../services/NavigationService';
import { SCREEN_ENUM } from '../../../../types/global';

interface ResponseProps {
  date: string;
  correctionNeeded: string;
  setCorrectionNeeded: (correctionNeeded: string) => void;
  setDate: (date: string) => void;
}

const Response = ({
  setDate,
  date,
  correctionNeeded,
  setCorrectionNeeded,
}: ResponseProps) => {
  const { t } = useAppTranslation();
  const [isExpanded, setIsExpanded] = useState(true);
  const [isDatePicker, setIsDatePicker] = useState(false);

  return (
    <View style={styles.container}>
      <View style={styles.header}>
        <Text style={styles.title}>{t('WARRANTY_RESPONSE')}</Text>
        <Button
          variant="ghost"
          style={styles.btnExpand}
          onPress={() => setIsExpanded(!isExpanded)}
        >
          <SvgXml
            xml={
              isExpanded
                ? IconChevronDown(colors.black)
                : IconChevronRight(colors.black)
            }
            width={SCREEN_WIDTH * 0.06}
            height={SCREEN_WIDTH * 0.06}
          />
        </Button>
      </View>

      {isExpanded && <View style={styles.line} />}

      {isExpanded && (
        <View style={styles.content}>
          <Text style={styles.instructionText}>
            {t(
              'PLEASE_SELECT_CORRECTION_DATE_AND_SELECT_MATERIALS_IF_NEEDED_FOR_THIS_WARRANTY_THEN_SUBMIT',
            )}
          </Text>

          <View style={styles.correctionDate}>
            <Text style={styles.label}>
              {t('CORRECTION_DATE')}
              <Text style={{ color: colors.error }}>*</Text>
            </Text>
            <Button
              variant="ghost"
              style={styles.inputRow}
              onPress={() => setIsDatePicker(true)}
            >
              <Text style={styles.dateText}>
                {date ? date : t('SELECT_A_DATE')}
              </Text>
              <SvgXml
                xml={IconCalendar(colors.twColors.text.darkGray)}
                width={SCREEN_WIDTH * 0.05}
                height={SCREEN_WIDTH * 0.05}
              />
            </Button>
          </View>

          <View style={styles.correctionNeeded}>
            <Text style={styles.label}>
              {t('CORRECTION_DATE')}
              <Text style={{ color: colors.error }}>*</Text>
            </Text>

            <Input
              style={styles.input}
              placeholder={t('ENTER_CORRECTION_NEEDED')}
              placeholderTextColor={colors.grayScale70}
              multiline
              onChangeText={setCorrectionNeeded}
              value={correctionNeeded}
            />
          </View>

          <Button
            variant="primary"
            style={styles.materialsButton}
            onPress={() =>
              NavigationService.navigate(SCREEN_ENUM.MaterialsWarrantyScreen)
            }
          >
            <Text style={styles.materialsButtonText}>{t('MATERIALS')}</Text>
            <SvgXml
              xml={IconChevronRight(colors.black)}
              width={SCREEN_WIDTH * 0.05}
              height={SCREEN_WIDTH * 0.05}
            />
          </Button>
        </View>
      )}

      <WheelDatePicker
        contentStyle={styles.contentWheelDatePicker}
        initialDate={dayjs().toDate()}
        isVisible={isDatePicker}
        cancelButtonOnPress={() => setIsDatePicker(false)}
        confirmButtonText={t('CONFIRM')}
        cancelButtonText={t('CANCEL')}
        title={t('SELECT_A_DATE')}
        cancelButtonStyle={styles.cancelButtonWheelDatePicker}
        confirmButtonStyle={styles.confirmButtonWheelDatePicker}
        cancelButtonTextStyle={styles.cancelButtonTextWheelDatePicker}
        confirmButtonOnPress={(date: string) => {
          if (!date) {
            setDate(dayjs().format('MM/DD/YYYY'));
          } else {
            setDate(date);
          }
          setIsDatePicker(false);
        }}
        titleStyle={styles.titleWheelDatePicker}
      />
    </View>
  );
};

export default Response;
