export enum USER_ROLE {
  OTHER = 0,
  LEADER = 1,
  INSPECTOR = 2,
  SUPPLIER = 3,
  INSTALLER = 4,
}

export interface RouteParams {
  taskId?: string;
  scheduleActivityId?: string;
  jobData?: any;
  roleType?: USER_ROLE;
}

export interface PhotoAttachment {
  uri?: string;
  fileName?: string;
  type?: string;
  direction?: string;
  area?: string;
  fileSize?: number;
}

export interface FileEntity {
  fileId: string;
  fileName: string;
  fileLength: number;
  fileExtension: string;
  key: string;
  url: string;
  direction?: string | null;
  area?: string | number | null;
}

export interface ProgressHistoryItem {
  historyId: string;
  sqft: number;
  updatedAt: string;
  updatedBy: string;
  updatedByName: string;
  note: string | null;
  fileEntities: FileEntity[];
  apiVersion: number;
}

export interface InstallationProgressData {
  scheduleActivityId: string;
  preSqft: number;
  currentSqft: number | null;
  remainingSqft: number | null;
  percentComplete: number | null;
  totalSqft: number;
  sqftHistories: ProgressHistoryItem[];
  completedToday: {
    sqft: number;
    percent: number;
  };
  startDateIns: string;
  addressData: {
    street: string;
    city: string | null;
    state: string | null;
    country: string | null;
  };
  address: string;
  companyName: string;
  communityCode: string;
  communityName: string;
  lotNumber: string;
  lotNumberRes: string;
  houseNumber: string;
  street: string | null;
  canEdit?: boolean;
  candEdit?: boolean;
}

export interface UploadResponse {
  success: boolean;
  loading: boolean;
  uploadFileUrl?: string;
  objectKey?: string;
  fileName?: string;
  fileType?: string;
  fileSize?: number;
  fileId?: string;
  QIresponseMessage?: string;
  originUrl?: string;
}
