import React from 'react';
import { View, ScrollView } from 'react-native';
import {
  BaseContainer,
  Button,
  HeaderBase,
  SCREEN_WIDTH,
  Text,
} from 'tradewize-component';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { SvgXml } from 'react-native-svg';
import { IconArrowDown2 } from '../../assets/svg';
import ChatContainer from '../../components/ChatContainer';
import Checklist from '../../components/Checklist';
import CommentChecklist from '../../components/CommentChecklist';
import useMaterialDelivered from './useMaterialDelivered';
import { styles } from './styles';
import { SCREEN_KEY_MATERIAL_DELIVERED } from '../../../../Auth/src/redux/features/jobDetail/contants';
class ChatErrorBoundary extends React.Component<
  { children: React.ReactNode; fallback: React.ReactNode },
  { hasError: boolean }
> {
  state = { hasError: false };
  static getDerivedStateFromError() {
    return { hasError: true };
  }
  componentDidCatch(error: any) {
    console.warn('[ChatErrorBoundary] ChatContainer crashed:', error);
  }
  render() {
    return this.state.hasError ? this.props.fallback : this.props.children;
  }
}

const MaterialDeliveredScreen = () => {
  const { t } = useAppTranslation();
  const {
    scrollViewRef,
    workOrderData,
    isLoading,
    isChatExpanded,
    supplierName,
    deliveredDate,
    resolvedChatId,
    handleGoBack,
    toggleChat,
  } = useMaterialDelivered();

  // Loading / empty state
  if (isLoading || !workOrderData) {
    return (
      <BaseContainer>
        <HeaderBase
          title={t('MATERIAL_CHECKLIST')}
          onPressBack={handleGoBack}
          backgroundColor={colors.white}
        />
      </BaseContainer>
    );
  }

  return (
    <BaseContainer>
      <HeaderBase
        title={t('MATERIAL_CHECKLIST')}
        onPressBack={handleGoBack}
        backgroundColor={colors.white}
      />

      <ScrollView
        ref={scrollViewRef}
        style={styles.container}
        contentContainerStyle={styles.contentContainer}
        showsVerticalScrollIndicator={false}
      >
        {/* Job Info */}
        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>{t('JOB_INFO')}</Text>
          </View>
          <View style={styles.sectionContent}>
            <View style={styles.infoRow}>
              <Text style={styles.infoLabel}>{t('LOT_NUMBER')}</Text>
              <Text style={styles.infoValue}>
                {workOrderData.houseInfo?.lotNumber || 'N/A'}
              </Text>
            </View>
            <View style={styles.infoRow}>
              <Text style={styles.infoLabel}>{t('ADDRESS')}</Text>
              <Text style={styles.infoValue}>
                {workOrderData.houseInfo?.street || 'N/A'}
              </Text>
            </View>
          </View>
        </View>

        {/* Supplier Detail */}
        <View style={styles.section}>
          <View style={styles.sectionHeader}>
            <Text style={styles.sectionTitle}>{t('SUPPLIER_DETAIL')}</Text>
          </View>
          <View style={styles.sectionContent}>
            <View style={styles.infoRow}>
              <Text style={styles.infoLabel}>{t('NAME')}</Text>
              <Text style={styles.infoValue}>{supplierName}</Text>
            </View>
            <View style={styles.infoRow}>
              <Text style={styles.infoLabel}>{t('DELIVERED_DATE')}</Text>
              <Text style={styles.infoValue}>{deliveredDate}</Text>
            </View>
          </View>
        </View>

        {/* Group Chat (Collapsible) */}
        <View style={styles.chatSection}>
          <Button style={[styles.chatHeader]} onPress={toggleChat}>
            <Text style={styles.sectionTitle}>{t('GROUP_CHAT')}</Text>
            <SvgXml
              xml={IconArrowDown2(colors.black)}
              width={SCREEN_WIDTH * 0.04}
              height={SCREEN_WIDTH * 0.04}
              style={isChatExpanded ? styles.iconRotated : undefined}
            />
          </Button>

          {isChatExpanded && (
            <View style={styles.chatContent}>
              {resolvedChatId ? (
                <ChatErrorBoundary
                  fallback={
                    <View style={styles.noChatContainer}>
                      <Text style={styles.noChatText}>
                        {t('NO_CHAT_AVAILABLE')}
                      </Text>
                    </View>
                  }
                >
                  <ChatContainer
                    chatId={resolvedChatId}
                    useScrollView={true}
                    isKeyboardInternallyHandled={false}
                    onFocusInput={() => {
                      setTimeout(() => {
                        scrollViewRef.current?.scrollToEnd({ animated: true });
                      }, 50);
                    }}
                    giftedChatProps={{ inverted: false }}
                  />
                </ChatErrorBoundary>
              ) : (
                <View style={styles.noChatContainer}>
                  <Text style={styles.noChatText}>
                    {t('NO_CHAT_AVAILABLE')}
                  </Text>
                </View>
              )}
            </View>
          )}
        </View>

        {/* Checklist — reads from Redux checklists keyed state */}
        {workOrderData?.checklists && workOrderData.checklists.length > 0 && (
          <Checklist screenKey={SCREEN_KEY_MATERIAL_DELIVERED} />
        )}
      </ScrollView>

      {/* Comment Checklist Modal */}
      <CommentChecklist />
    </BaseContainer>
  );
};

export default MaterialDeliveredScreen;
