import { useState, useEffect, useRef, useCallback } from 'react';
import {
  ScrollView,
  Alert,
  Keyboard,
  Platform,
  AppState,
  Linking,
} from 'react-native';
import { useTranslation } from 'react-i18next';
import { useRoute } from '@react-navigation/native';
import ImagePicker from 'react-native-image-crop-picker';
import {
  check,
  Permission,
  PERMISSIONS,
  request,
  RESULTS,
} from 'react-native-permissions';
import ImageCompressor from 'react-native-compressor';
import { useSafeAreaInsets } from 'react-native-safe-area-context';
import Toast from 'react-native-toast-message';
import axios from 'axios';

import { NavigationService } from '../../services/NavigationService';
import {
  getInstallationProgress,
  getPresignedUrl,
  updateInstallationProgress,
} from '../../api/endpoint';
import { logger } from '../../utils';

import {
  RouteParams,
  PhotoAttachment,
  InstallationProgressData,
  UploadResponse,
  USER_ROLE,
  ProgressHistoryItem,
} from './types';
import {
  delay,
  getRandomNumbers,
  checkIfSubmittedToday,
  getTodaySqftFromHistory,
  getLatestTodayEntry,
  sumArea,
} from './helpers';

export function useInstallationProgress() {
  const { t } = useTranslation();
  const route = useRoute();
  const insets = useSafeAreaInsets();
  const { scheduleActivityId, jobData } = (route.params as RouteParams) || {};

  // State
  const [sqftInstalled, setSqftInstalled] = useState('');
  const [totalSqft, setTotalSqft] = useState('');
  const [initialSqft, setInitialSqft] = useState('');
  const [preSqft, setPreSqft] = useState(0);
  const [maxTodaySqft, setMaxTodaySqft] = useState(0);
  const [keyboardOffset, setKeyboardOffset] = useState(0);

  const [photos, setPhotos] = useState<PhotoAttachment[]>([]);
  const [uploadResults, setUploadResults] = useState<any[]>([]);
  const [isUploading, setIsUploading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [installationData, setInstallationData] =
    useState<InstallationProgressData | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isFocused, setIsFocused] = useState(false);
  const [errorSqft, setErrorSqft] = useState<string | null>(null);
  const [isShowBtn, setIsShowBtn] = useState(true);
  const [comment, setComment] = useState('');
  const [showHistoryModal, setShowHistoryModal] = useState(false);
  const [selectedImageUrl, setSelectedImageUrl] = useState<string | null>(null);
  const [hasSubmittedToday, setHasSubmittedToday] = useState(false);
  const [showEditModal, setShowEditModal] = useState(false);

  // Edit modal state
  const [editModalSqft, setEditModalSqft] = useState('');
  const [editModalPhotos, setEditModalPhotos] = useState<PhotoAttachment[]>([]);
  const [editModalUploadResults, setEditModalUploadResults] = useState<any[]>(
    [],
  );
  const [editModalComment, setEditModalComment] = useState('');
  const [editModalErrorSqft, setEditModalErrorSqft] = useState<string | null>(
    null,
  );

  // Refs
  const scrollViewRef = useRef<ScrollView | null>(null);
  const editModalScrollViewRef = useRef<ScrollView | null>(null);

  // Derived values
  const progressHistoryData: ProgressHistoryItem[] =
    installationData?.sqftHistories || [];
  const canEdit =
    installationData?.candEdit === true || installationData?.canEdit === true;

  // Permission helpers
  const requestPermission = async (permission: any) => {
    const result = await request(permission);
    if (result === RESULTS.GRANTED) {
      return true;
    } else {
      Alert.alert(
        t('PERMISSION_DENIED'),
        t('PLEASE_ACCESS_PERMISSION_IN_SETTINGS'),
        [
          { text: t('CLOSE'), style: 'cancel' },
          { text: t('OPEN_SETTINGS'), onPress: () => Linking.openSettings() },
        ],
      );
    }
  };

  const checkPermissionHandler = async (
    iosPer?: Permission,
    androidPer?: Permission,
    onBlocked?: () => void,
  ): Promise<boolean> => {
    try {
      const permissionType = Platform.OS === 'ios' ? iosPer : androidPer;
      if (!permissionType) {
        return false;
      }

      let result = await check(permissionType);

      if (result === RESULTS.DENIED || result === RESULTS.UNAVAILABLE) {
        const granted = await requestPermission(permissionType);
        return granted ?? false;
      }

      switch (result) {
        case RESULTS.GRANTED:
          return true;
        case RESULTS.LIMITED:
          requestPermission(permissionType);
          return true;
        case RESULTS.BLOCKED:
          if (onBlocked) {
            onBlocked();
          }
          requestPermission(permissionType);
          return false;
        default:
          return false;
      }
    } catch (err) {
      console.error('Permission check error:', err);
      return false;
    }
  };

  // S3 Upload
  const uploadFileS3 = async (
    file: any,
    folderName: string,
    onLoadingChange?: (loading: boolean) => void,
    onProgressChange?: (percent: number) => void,
    role?: USER_ROLE,
    isPhoto?: boolean,
  ): Promise<UploadResponse> => {
    try {
      const client = await import('auth/api');
      const randomNumbers = getRandomNumbers(5);

      onLoadingChange?.(true);
      onProgressChange?.(0);

      const fileData = file.originFileObj || {};
      let resMessage = '';

      if (!fileData) {
        Alert.alert('Error', 'No file data found');
        onProgressChange?.(100);
        return { success: false, loading: false };
      }

      const uploadFileData: any = {
        folder: folderName,
        fileName: file.name,
        contentType: file.type || 'application/octet-stream',
      };
      onProgressChange?.(randomNumbers[0]);

      const response = await client.postRequest(
        getPresignedUrl,
        uploadFileData,
      );
      if (response?.status === 200 && response?.data) {
        const {
          url: presignedUrl,
          key: objectKey,
          s3BaseUrl,
          fileId,
        } = response.data;

        if (!presignedUrl || typeof presignedUrl !== 'string') {
          Alert.alert('Error', 'Invalid presigned URL');
          return { success: false, loading: false };
        }

        onProgressChange?.(randomNumbers[1]);

        try {
          const fileDataTest = await fetch(fileData?.uri).then(res =>
            res.blob(),
          );

          await axios.put(presignedUrl, fileDataTest, {
            headers: {
              'Content-Type': file.type || 'application/octet-stream',
            },
            transformRequest: (data, headers) => {
              delete headers.Accept;
              delete headers['Content-Length'];
              return data;
            },
          });
        } catch (putError) {
          onProgressChange?.(100);
          Alert.alert(
            t('UPLOAD_FAILED'),
            t('FAILED_TO_UPLOAD_FILE_TO_SEVER_PLEASE_TRY_AGAIN_LATER'),
          );
          return { success: false, loading: false };
        } finally {
          onProgressChange?.(randomNumbers[2]);
        }

        if (
          (role === USER_ROLE.INSPECTOR || role === USER_ROLE.LEADER) &&
          isPhoto
        ) {
          try {
            const qiData = {
              images: [{ url: response.data.fileUrl }],
            };
            const qiConfig = {
              method: 'post',
              url: process.env.SIDING_INSPECTOR_LAMBDA_URL,
              headers: { 'Content-Type': 'application/json' },
              data: qiData,
            };
            const qiResponse = await axios.request(qiConfig);
            if (qiResponse.status === 200) {
              resMessage = qiResponse.data.response;
            }
          } catch (err) {
            onProgressChange?.(100);
            logger('Error calling QI Images API:', err);
          } finally {
            onProgressChange?.(randomNumbers[3]);
          }
        }

        const uploadFileUrl = `${
          s3BaseUrl || process.env.S3_BASE_URL
        }/${objectKey}`;
        onProgressChange?.(randomNumbers[4]);
        await delay(500);
        onProgressChange?.(100);
        await delay(300);

        return {
          success: true,
          loading: false,
          uploadFileUrl,
          objectKey,
          fileId,
          fileName: file.name,
          fileType: file.type || 'application/octet-stream',
          fileSize: file.size,
          originUrl: response.data.fileUrl,
          QIresponseMessage: resMessage,
        };
      } else {
        onProgressChange?.(100);
        Alert.alert('Error', 'Failed to get presigned URL');
        return { success: false, loading: false };
      }
    } catch (err) {
      const error = err as any;
      logger('Upload error:', error, error?.response);
      Alert.alert('Error', 'An error occurred during upload');
      onProgressChange?.(100);
      return { success: false, loading: false };
    } finally {
      onLoadingChange?.(false);
      onProgressChange?.(0);
    }
  };

  // SQFT handlers
  const handleSqftChange = useCallback(
    (text: string) => {
      let normalized = text.replace(/,/g, '.');
      const parts = normalized.split('.');
      if (parts.length > 2) {
        normalized =
          parts[0] + '.' + parts.slice(1).join('').replace(/\./g, '');
      }

      let cleanedText = normalized?.replace(/[^0-9.]/g, '');
      const decimalCount = (cleanedText.match(/\./g) || []).length;
      if (decimalCount > 1) {
        cleanedText = cleanedText.replace(/\./g, '').replace(/(\d+)/, '$1.');
      }

      if (cleanedText.includes('.')) {
        const parts = cleanedText.split('.');
        if (parts[1] && parts[1].length > 2) {
          cleanedText = parts[0] + '.' + parts[1].substring(0, 2);
        }
      }

      if (Number(cleanedText) > maxTodaySqft) {
        setErrorSqft(
          t(
            'THE_NUMBER_OF_SQUARES_ENTERED_EXCEEDS_THE_PERMITTED_LIMIT_PLEASE_REVIEW_YOUR_INPUT',
          ),
        );
      } else {
        setErrorSqft(null);
      }

      setSqftInstalled(cleanedText);
    },
    [maxTodaySqft, t],
  );

  const handleEditModalSqftChange = useCallback(
    (text: string) => {
      let normalized = text.replace(/,/g, '.');
      const parts = normalized.split('.');
      if (parts.length > 2) {
        normalized =
          parts[0] + '.' + parts.slice(1).join('').replace(/\./g, '');
      }

      let cleanedText = normalized?.replace(/[^0-9.]/g, '');
      const decimalCount = (cleanedText.match(/\./g) || []).length;
      if (decimalCount > 1) {
        cleanedText = cleanedText.replace(/\./g, '').replace(/(\d+)/, '$1.');
      }

      if (cleanedText.includes('.')) {
        const parts = cleanedText.split('.');
        if (parts[1] && parts[1].length > 2) {
          cleanedText = parts[0] + '.' + parts[1].substring(0, 2);
        }
      }

      if (Number(cleanedText) > maxTodaySqft) {
        setEditModalErrorSqft(
          t(
            'THE_NUMBER_OF_SQUARES_ENTERED_EXCEEDS_THE_PERMITTED_LIMIT_PLEASE_REVIEW_YOUR_INPUT',
          ),
        );
      } else {
        setEditModalErrorSqft(null);
      }

      setEditModalSqft(cleanedText);
    },
    [maxTodaySqft, t],
  );

  // Fetch data
  const fetchInstallationProgress = async (skipLoading: boolean = false) => {
    const client = await import('auth/api');
    if (!scheduleActivityId) {
      setError('Schedule Activity ID is required');
      if (!skipLoading) {
        setLoading(false);
      }
      return;
    }

    try {
      if (!skipLoading) {
        setLoading(true);
      }
      setError(null);

      const response = await client.getRequest(
        `${getInstallationProgress}/${scheduleActivityId}`,
      );

      if (response && response.status === 200) {
        const data = response.data;
        setInstallationData(data);
        setTotalSqft(data.totalSqft?.toString() || '0');
        const currentSqft = data.currentSqft?.toString() || '';
        setInitialSqft(currentSqft);

        const preSqftValue = data.preSqft ?? 0;
        setPreSqft(preSqftValue);
        const totalSqftValue = data.totalSqft ?? 0;
        const maxTodaySqftValue = totalSqftValue - preSqftValue;
        setMaxTodaySqft(Math.max(0, maxTodaySqftValue));

        const todaySqftFromHistory = getTodaySqftFromHistory(
          data.sqftHistories || [],
        );
        const submittedFromHistory = checkIfSubmittedToday(
          data.sqftHistories || [],
        );

        if (submittedFromHistory) {
          const latestEntry = getLatestTodayEntry(data.sqftHistories || []);
          if (latestEntry) {
            setSqftInstalled(latestEntry.sqft?.toString() || '');
            setComment(latestEntry.note || '');

            if (
              latestEntry.fileEntities &&
              latestEntry.fileEntities.length > 0
            ) {
              const loadedPhotos: PhotoAttachment[] =
                latestEntry.fileEntities.map(file => ({
                  uri: file.url,
                  fileName: file.fileName,
                  type: file.fileExtension
                    ? `image/${file.fileExtension}`
                    : 'image/jpeg',
                  direction: file.direction || undefined,
                  area:
                    file.area !== undefined && file.area !== null
                      ? String(file.area)
                      : undefined,
                }));
              setPhotos(loadedPhotos);

              const loadedUploadResults = latestEntry.fileEntities.map(
                file => ({
                  fileId: file.fileId,
                  fileName: file.fileName,
                  fileSize: file.fileLength,
                  fileType: file.fileExtension
                    ? `image/${file.fileExtension}`
                    : 'image/jpeg',
                  objectKey: file.key,
                  uploadFileUrl: file.url,
                  originUrl: file.url,
                  success: true,
                }),
              );
              setUploadResults(loadedUploadResults);
            } else {
              setPhotos([]);
              setUploadResults([]);
            }
          } else {
            setSqftInstalled('');
            setComment('');
            setPhotos([]);
            setUploadResults([]);
          }
        } else if (todaySqftFromHistory) {
          setSqftInstalled(todaySqftFromHistory);
        } else {
          setSqftInstalled('');
          setComment('');
          setPhotos([]);
          setUploadResults([]);
        }

        setHasSubmittedToday(submittedFromHistory);

        const currentSqftNum = Number(currentSqft) || 0;
        const totalSqftNum = Number(data?.totalSqft) || 0;

        if (totalSqftNum > 0 && currentSqftNum >= totalSqftNum) {
          setIsShowBtn(false);
        } else {
          setIsShowBtn(true);
        }
      } else {
        setError(
          response.data?.message || 'Failed to fetch installation progress',
        );
      }
    } catch (err) {
      setError('Failed to fetch installation progress');
    } finally {
      if (!skipLoading) {
        setLoading(false);
      }
    }
  };

  // Camera & photo handlers
  const handleCameraPicker = async (direction: string, area: string) => {
    if (photos.length >= 5) {
      Toast.show({
        type: 'error',
        text1: t('LIMIT_5_IMAGES'),
      });
      return;
    }

    const granted = await checkPermissionHandler(
      PERMISSIONS.IOS.CAMERA,
      PERMISSIONS.ANDROID.CAMERA,
    );

    if (!granted) {
      return;
    }
    const result = await ImagePicker.openCamera({
      mediaType: 'photo',
      cropping: false,
    });

    if (result?.path) {
      const asset: PhotoAttachment = {
        uri: result.path,
        type: result.mime || 'image/jpeg',
        fileName: result.path.split('/').pop() || `photo_${Date.now()}.jpg`,
      };
      await handlePhotoUpload(asset, direction, area);
    }
  };

  const handleRemovePhoto = (index: number) => {
    const newPhotos = [...photos];
    const newUploadResults = [...uploadResults];
    newPhotos.splice(index, 1);
    newUploadResults.splice(index, 1);
    setPhotos(newPhotos);
    setUploadResults(newUploadResults);
    const hasEmptyArea = newPhotos.some(item => !item.area);
    const sumAreaValue = !hasEmptyArea ? sumArea(newPhotos).toString() : '';
    handleSqftChange(sumAreaValue);
  };

  const handlePhotoAreaChange = (index: number, area: string) => {
    setPhotos(prevPhotos => {
      if (!prevPhotos[index]) {
        return prevPhotos;
      }
      const updatedPhotos = [...prevPhotos];
      updatedPhotos[index] = {
        ...updatedPhotos[index],
        area,
      };
      return updatedPhotos;
    });
    const newPhotos = [...photos];
    newPhotos[index] = {
      ...newPhotos[index],
      area,
    };
    const hasEmptyArea = newPhotos.some(item => !item.area);
    const sumAreaValue = !hasEmptyArea ? sumArea(newPhotos).toString() : '';
    handleSqftChange(sumAreaValue);
  };

  const handlePhotoUpload = async (
    asset: PhotoAttachment,
    direction: string,
    area: string,
  ) => {
    if (!asset.uri) return;

    setIsUploading(true);
    try {
      const compressedImage = await ImageCompressor.Image.compress(asset.uri, {
        maxWidth: 1920,
        maxHeight: 1920,
        quality: 0.8,
      });

      const compressedAsset: PhotoAttachment = {
        ...asset,
        uri: compressedImage,
        fileSize: undefined,
        direction: direction,
        area: area,
      };
      const fileObj = {
        uri: compressedImage,
        type: asset.type || 'image/jpeg',
        name:
          asset.fileName ||
          `photo_${Date.now()}.${asset.type?.split('/')[1] || 'jpg'}`,
        size: 0,
      };

      const uploadResult = await uploadFileS3(
        {
          originFileObj: fileObj,
          name: fileObj.name,
          type: fileObj.type,
          size: fileObj.size,
        },
        'installation-progress',
        (loadingState: boolean) => {
          setIsUploading(loadingState);
        },
      );

      if (uploadResult?.success) {
        setPhotos(prev => [...prev, compressedAsset]);
        setUploadResults(prev => [...prev, uploadResult]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('PHOTO_UPLOAD_FAILED'),
        });
      }
    } catch (err) {
      console.error('Photo compression/upload error:', err);
      setError('Photo upload error');
    } finally {
      setIsUploading(false);
    }
  };

  // Edit modal handlers
  const handleEditModalPhotoUpload = async (
    asset: PhotoAttachment,
    direction: string,
    area: string,
  ) => {
    if (!asset.uri) return;

    setIsUploading(true);
    try {
      const compressedImage = await ImageCompressor.Image.compress(asset.uri, {
        maxWidth: 1920,
        maxHeight: 1920,
        quality: 0.8,
      });

      const compressedAsset: PhotoAttachment = {
        ...asset,
        uri: compressedImage,
        fileSize: undefined,
        direction,
        area,
      };
      const fileObj = {
        uri: compressedImage,
        type: asset.type || 'image/jpeg',
        name:
          asset.fileName ||
          `photo_${Date.now()}.${asset.type?.split('/')[1] || 'jpg'}`,
        size: 0,
      };

      const uploadResult = await uploadFileS3(
        {
          originFileObj: fileObj,
          name: fileObj.name,
          type: fileObj.type,
          size: fileObj.size,
        },
        'installation-progress',
        (loadingState: boolean) => {
          setIsUploading(loadingState);
        },
      );

      if (uploadResult?.success) {
        setEditModalPhotos(prev => [...prev, compressedAsset]);
        setEditModalUploadResults(prev => [...prev, uploadResult]);
      } else {
        Toast.show({
          type: 'error',
          text1: t('PHOTO_UPLOAD_FAILED'),
        });
      }
    } catch (err) {
      console.error('Photo compression/upload error:', err);
      setError('Photo upload error');
    } finally {
      setIsUploading(false);
    }
  };

  const handleEditModalPhotoAreaChange = (index: number, area: string) => {
    setEditModalPhotos(prevPhotos => {
      if (!prevPhotos[index]) {
        return prevPhotos;
      }
      const updatedPhotos = [...prevPhotos];
      updatedPhotos[index] = {
        ...updatedPhotos[index],
        area,
      };
      return updatedPhotos;
    });
    const newPhotos = [...editModalPhotos];
    newPhotos[index] = {
      ...newPhotos[index],
      area,
    };
    const hasEmptyArea = newPhotos.some(item => !item.area);
    const sumAreaValue = !hasEmptyArea ? sumArea(newPhotos).toString() : '';
    handleEditModalSqftChange(sumAreaValue);
  };

  // Submit / Update
  const handleUpdate = async (
    customSqft?: string,
    customPhotos?: PhotoAttachment[],
    customUploadResults?: any[],
    customComment?: string,
  ): Promise<boolean> => {
    Keyboard.dismiss();

    if (
      isSubmitting ||
      !!errorSqft ||
      !sqftInstalled ||
      parseFloat(sqftInstalled || '0') > maxTodaySqft
    ) {
      Alert.alert(t('ERROR'), t('PLEASE_FILL_ALL_INFORMATION'));
      return false;
    }

    const sqftValue = customSqft !== undefined ? customSqft : sqftInstalled;
    const photosValue = customPhotos !== undefined ? customPhotos : photos;
    const uploadResultsValue =
      customUploadResults !== undefined ? customUploadResults : uploadResults;
    const commentValue = customComment !== undefined ? customComment : comment;

    const errors: string[] = [];
    if (!sqftValue || sqftValue.trim() === '') {
      errors.push(t('PLEASE_ENTER_SQFT_INSTALLED'));
    }

    const sqftNumber = parseFloat(sqftValue || '0');

    if (isNaN(sqftNumber) || sqftNumber < 0) {
      Alert.alert('Error', 'Please enter a valid number for square feet');
      return false;
    }

    if (sqftNumber > maxTodaySqft) {
      Alert.alert(
        'Error',
        'The number of squares entered exceeds the permitted limit. Please review your input.',
      );
      return false;
    }

    if (sqftNumber === 0) {
      if (!commentValue || commentValue.trim() === '') {
        errors.push(t('PLEASE_ENTER_NOTE_WHEN_SQFT_IS_ZERO'));
      }
    }

    if (!photosValue || photosValue.length === 0) {
      errors.push(t('PLEASE_TAKE_PHOTOS_BEFORE_UPDATE'));
    }

    if (errors.length > 0) {
      Alert.alert(t('REQUIRED_INFORMATION_MISSING'), errors.join('\n\n'));
      return false;
    }

    setIsSubmitting(true);
    try {
      const client = await import('auth/api');
      const files = uploadResultsValue.map((uploadResult, index) => {
        const relatedPhoto = photosValue?.[index];
        return {
          fileId: uploadResult.fileId,
          fileName: uploadResult.fileName,
          fileLength: uploadResult.fileSize || 0,
          fileExtension: uploadResult.fileType?.split('/')[1] || 'jpg',
          key: uploadResult.objectKey || '',
          url: uploadResult.uploadFileUrl || uploadResult.originUrl || '',
          direction: relatedPhoto?.direction || '',
          area: relatedPhoto?.area || '',
        };
      });

      const requestBody = {
        scheduleActivityId: scheduleActivityId,
        sqft: sqftNumber,
        files: files,
        note: commentValue.trim(),
      };

      const response = await client.putRequest(
        updateInstallationProgress,
        requestBody,
      );

      if (response && response.status === 200) {
        setSqftInstalled(sqftValue);
        setPhotos(photosValue);
        setUploadResults(uploadResultsValue);
        setComment(commentValue);
        setHasSubmittedToday(true);

        await fetchInstallationProgress(true);

        Alert.alert(
          t('SUCCESS'),
          t('INSTALLATION_PROGRESS_SUBMITTED_SUCCESSFULLY'),
          [
            {
              text: 'OK',
              onPress: () => {
                NavigationService.goBack();
              },
            },
          ],
        );
        return true;
      } else {
        Alert.alert(
          'Error',
          response.data?.message || t('FAILED_TO_SUBMIT_INSTALLATION_PROGRESS'),
        );
        return false;
      }
    } catch {
      setError(t('ERROR_SUBMIT_INSTALLATION_PROGRESS'));
      return false;
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
    NavigationService.goBack();
  };

  // Progress calculation
  const calculateProgressPercentage = () => {
    if (!installationData || !totalSqft || parseFloat(totalSqft) === 0) {
      return installationData?.percentComplete ?? 0;
    }

    if (hasSubmittedToday) {
      return installationData?.percentComplete ?? 0;
    }

    if (sqftInstalled && sqftInstalled.trim() !== '') {
      const sqftValue = parseFloat(sqftInstalled);
      if (!isNaN(sqftValue) && sqftValue >= 0) {
        const totalSqftValue = parseFloat(totalSqft);
        const calculatedPercent =
          ((preSqft + sqftValue) / totalSqftValue) * 100;
        return Math.min(100, Math.max(0, calculatedPercent));
      }
    }

    return installationData?.percentComplete ?? 0;
  };

  // Effects
  useEffect(() => {
    fetchInstallationProgress();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [scheduleActivityId]);

  useEffect(() => {
    const subscription = AppState.addEventListener('change', nextState => {
      if (nextState !== 'active') {
        Keyboard.dismiss();
      }
    });

    return () => {
      subscription.remove();
    };
  }, []);

  const progressPercentage = calculateProgressPercentage();

  return {
    // State
    t,
    insets,
    scheduleActivityId,
    jobData,
    sqftInstalled,
    totalSqft,
    initialSqft,
    preSqft,
    maxTodaySqft,
    keyboardOffset,
    photos,
    uploadResults,
    isUploading,
    isSubmitting,
    installationData,
    loading,
    error,
    isFocused,
    errorSqft,
    isShowBtn,
    comment,
    showHistoryModal,
    selectedImageUrl,
    hasSubmittedToday,
    showEditModal,
    editModalSqft,
    editModalPhotos,
    editModalUploadResults,
    editModalComment,
    editModalErrorSqft,
    progressHistoryData,
    canEdit,
    progressPercentage,

    // Refs
    scrollViewRef,
    editModalScrollViewRef,

    // Setters
    setKeyboardOffset,
    setIsFocused,
    setComment,
    setShowHistoryModal,
    setSelectedImageUrl,
    setShowEditModal,
    setEditModalSqft,
    setEditModalPhotos,
    setEditModalUploadResults,
    setEditModalComment,
    setEditModalErrorSqft,
    setError,
    setLoading,

    // Handlers
    handleSqftChange,
    handleEditModalSqftChange,
    handleCameraPicker,
    handleRemovePhoto,
    handlePhotoAreaChange,
    handleEditModalPhotoUpload,
    handleEditModalPhotoAreaChange,
    handleUpdate,
    handleClose,
    fetchInstallationProgress,
    checkPermission: checkPermissionHandler,
  };
}
