import React, { useCallback } from 'react';
import {
  ActivityIndicator,
  FlatList,
  RefreshControl,
  View,
} from 'react-native';
import { BaseContainer, Button, HeaderBase, Text } from 'tradewize-component';
import { styles } from './styles';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { colors } from '../../theme';
import { NavigationService } from '../../services/NavigationService';
import { useInspectionRequests } from './useInspectionRequests';
import { InspectionRequest } from './types';

import RequestItem from './component/RequestItem';
import EmptyState from './component/EmptyState';
import FilterBottomSheet from './component/FilterBottomSheet';

const InspectionRequestsScreen = () => {
  const { t } = useAppTranslation();

  const {
    inspectionRequests,
    selectedItems,
    loadingMore,
    refreshing,
    isLoading,
    handleLoadMore,
    handleRefresh,
    handleItemPress,
    handleRegister,
  } = useInspectionRequests();

  // ---------- FlatList helpers ----------

  const renderItem = useCallback(
    ({ item }: { item: InspectionRequest }) => (
      <RequestItem
        item={item}
        isCheck={selectedItems.has(item.id)}
        onClickItem={() => handleItemPress(item.id)}
      />
    ),
    [selectedItems, handleItemPress],
  );

  const keyExtractor = useCallback((item: InspectionRequest) => item.id, []);

  const renderEmpty = useCallback(() => {
    if (!refreshing && !loadingMore && !isLoading) {
      return <EmptyState />;
    }
    return null;
  }, [refreshing, loadingMore, isLoading]);

  const renderFooter = useCallback(() => {
    if (!loadingMore) return null;
    return (
      <View style={styles.loadingMoreContainer}>
        <ActivityIndicator size="small" color={colors.twColors.primary} />
      </View>
    );
  }, [loadingMore]);

  // ---------- Render ----------

  return (
    <BaseContainer style={styles.container}>
      <HeaderBase
        onPressBack={() => NavigationService.goBack()}
        title={t('LABELS_INSPECTION_REQUESTS')}
      />
      <Text style={styles.text}>
        {t('TRADE_WIZE_NEEDS_INSPECTION_AT_ADDRESS')}
      </Text>
      <Text style={styles.text}>
        {t('PLEASE_ACCEPT_BELOW_IF_YOU_ARE_IN_THE_AREA_AND_ABLE_TO_INSPECT')}
      </Text>

      <FlatList
        style={styles.list}
        data={inspectionRequests}
        renderItem={renderItem}
        keyExtractor={keyExtractor}
        onEndReached={handleLoadMore}
        onEndReachedThreshold={0.1}
        refreshControl={
          <RefreshControl refreshing={refreshing} onRefresh={handleRefresh} />
        }
        ListEmptyComponent={renderEmpty}
        ListFooterComponent={renderFooter}
      />

      <View style={styles.registerButtonContainer}>
        <Button onPress={handleRegister} style={styles.registerButton}>
          <Text style={styles.registerButtonText}>{t('REGISTER')}</Text>
        </Button>
      </View>

      <FilterBottomSheet />
    </BaseContainer>
  );
};

export default InspectionRequestsScreen;
