import React, {
  useState,
  useEffect,
  useCallback,
  useRef,
  useMemo,
} from 'react';
import { useFocusEffect } from '@react-navigation/native';
import { TabView, SceneMap } from 'react-native-tab-view';
import { BaseContainer, HeaderBase, SCREEN_WIDTH } from 'tradewize-component';
import ScreenTab, { renderTabBar } from './components/ScreenTab';
import FilterModal, { FilterModalRef } from './components/FilterModal';
import { NavigationService } from '../../services/NavigationService';
import { useDispatch, useSelector } from 'react-redux';
import { SvgXml } from 'react-native-svg';
import { IconFilter } from '../../assets/svg';
import { colors } from '../../theme';
import { STATUS_MAP, STATUS_SORT_BY } from '../../helper/myJob.helper';
import { JobStartTabStatus } from '../../types/myJobs.types';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { actionMyJobs } from '../../../../Auth/src/redux/features/myjob/actions';
import CalenderPicker from './components/CalenderPicker';
import { styles } from './styles';
import { Image, View } from 'react-native';
import { calendar, playInstructionalVideos } from '../../assets/images';
import GanttView from './components/GanttView';
import VideoSelectionModal, {
  VideoOption,
  VideoSelectionModalRef,
} from './components/VideoSelectionModal';

// Define scene components outside the render function
const InProgressScene = () => (
  <ScreenTab tabType={JobStartTabStatus.IN_PROGRESS} />
);
const NotStartedScene = () => (
  <ScreenTab tabType={JobStartTabStatus.NOT_STARTED} />
);
const CompletedScene = () => (
  <ScreenTab tabType={JobStartTabStatus.COMPLETED} />
);

export default function MyJobsScreen() {
  const dispatch = useDispatch();
  const { t } = useAppTranslation();

  const [index, setIndex] = useState(0);
  const [filterParams, setFilterParams] = useState<{
    CommunityId?: string;
    LotNumber?: string;
    StartDate?: string;
    EndDate?: string;
  }>({});
  const filterModalRef = useRef<FilterModalRef>(null);
  const language = useSelector((state: any) => state.app.language);
  const mediaState = useSelector((state: any) => state.app?.dataMedia);

  const [rangeDate, setRangeDate] = useState<{
    startDate: string;
    endDate: string;
  }>({
    startDate: '',
    endDate: '',
  });
  const [isFocusedCalendar, setIsFocusedCalendar] = useState(false);
  const [isFocusedGrantView, setIsFocusedGrantView] = useState(false);
  const videoSelectionRef = useRef<VideoSelectionModalRef>(null);

  const [routes] = useState([
    { key: JobStartTabStatus.IN_PROGRESS, title: t('IN_PROGRESS') },
    { key: JobStartTabStatus.NOT_STARTED, title: t('NOT_STARTED') },
    { key: JobStartTabStatus.COMPLETED, title: t('COMPLETED') },
  ]);

  const communitiesData = useSelector(
    (state: any) => state.myjob.communities.data,
  );

  const fetchMyJobs = useCallback(() => {
    const status = STATUS_MAP[routes[index].key];
    const params = {
      Status: status,
      SortBy: STATUS_SORT_BY[routes[index].key],
      PageIndex: 1,
      ...(filterParams.CommunityId && {
        CommunityId: filterParams.CommunityId,
      }),
      ...(filterParams.LotNumber && { LotNumber: filterParams.LotNumber }),
      ...(filterParams.StartDate && { StartDate: filterParams.StartDate }),
      ...(filterParams.EndDate && { EndDate: filterParams.EndDate }),
    };

    const redux = require('auth/redux');
    dispatch(redux.actionContainer.getMyJobsAsync(params));
  }, [index, filterParams, routes, dispatch]);

  const videoOptions = useMemo(() => {
    return [
      {
        id: '1',
        title: t('WHAT_DO_I_DO_WHEN_I_GET_TO_THE_JOB_SITE'),
        url: mediaState?.['1_MYJOBS_SCREENS' as keyof typeof mediaState]
          ?.url || { en: '', es: '' },
        subtitle:
          mediaState?.['1_MYJOBS_SCREENS' as keyof typeof mediaState]
            ?.subtitle || {},
      },
      {
        id: '2',
        title: t('WHAT_DO_I_DO_IF_I_CANT_MAKE_THE_JOB'),
        url: mediaState?.['2_MYJOBS_SCREENS' as keyof typeof mediaState]
          ?.url || { en: '', es: '' },
        subtitle:
          mediaState?.['2_MYJOBS_SCREENS' as keyof typeof mediaState]
            ?.subtitle || {},
      },
      {
        id: '3',
        title: t('WHAT_HAPPENS_IF_A_JOB_IS_DELAYED'),
        url: mediaState?.['3_MYJOBS_SCREENS' as keyof typeof mediaState]
          ?.url || { en: '', es: '' },
        subtitle:
          mediaState?.['3_MYJOBS_SCREENS' as keyof typeof mediaState]
            ?.subtitle || {},
      },
    ];
  }, [mediaState, t]);

  const fetchGanttData = useCallback(() => {
    const redux = require('auth/redux');

    const allStatuses = [
      JobStartTabStatus.NOT_STARTED,
      JobStartTabStatus.IN_PROGRESS,
      JobStartTabStatus.COMPLETED,
    ];

    const paramsList = allStatuses.map(statusKey => ({
      Status: STATUS_MAP[statusKey],
      SortBy: STATUS_SORT_BY[statusKey],
      PageIndex: 1,
      ...(filterParams.CommunityId && {
        CommunityId: filterParams.CommunityId,
      }),
      ...(filterParams.LotNumber && { LotNumber: filterParams.LotNumber }),
      ...(filterParams.StartDate && { StartDate: filterParams.StartDate }),
      ...(filterParams.EndDate && { EndDate: filterParams.EndDate }),
    }));

    dispatch(redux.actionContainer.getGanttDataAsync(paramsList));
  }, [filterParams, dispatch]);

  const fetchCommunities = useCallback(() => {
    const redux = require('auth/redux');
    dispatch(redux.actionContainer.getCommunitiesAsync());
  }, [dispatch]);

  useEffect(() => {
    fetchCommunities();
  }, [fetchCommunities]);

  // Re-fetch My Jobs every time screen gets focus (including goBack from other screens)
  useFocusEffect(
    useCallback(() => {
      fetchMyJobs();
    }, [fetchMyJobs]),
  );

  useEffect(() => {
    if (isFocusedGrantView) {
      fetchGanttData();
    }
  }, [fetchGanttData, isFocusedGrantView]);

  // Save filter params to Redux when tab or filter changes
  useEffect(() => {
    dispatch(
      actionMyJobs.setMyJobFilterParams({
        tabIndex: index,
        filter: filterParams,
      }),
    );
  }, [index, filterParams, dispatch]);

  const handleFilterPress = useCallback(() => {
    filterModalRef.current?.open();
  }, []);

  const handleApplyFilter = useCallback(
    (newFilters: {
      CommunityId?: string;
      LotNumber?: string;
      StartDate?: string;
      EndDate?: string;
    }) => {
      setFilterParams(newFilters);
    },
    [],
  );

  const handleResetFilter = useCallback(() => {
    setFilterParams({});
  }, []);

  const handleCloseFilter = useCallback(() => {
    // Bottom sheet handles its own close animation
  }, []);

  const handleGrantView = useCallback(() => {
    setIsFocusedGrantView(prev => !prev);
  }, []);

  const handleOpenVideoInstructional = useCallback(() => {
    try {
      videoSelectionRef.current?.open();
    } catch (error) {
      console.log('error handleOpenVideoInstructional', error);
    }
  }, []);

  const renderScene = SceneMap({
    [JobStartTabStatus.IN_PROGRESS]: InProgressScene,
    [JobStartTabStatus.NOT_STARTED]: NotStartedScene,
    [JobStartTabStatus.COMPLETED]: CompletedScene,
  });

  const activeFilterCount = Object.keys(filterParams).filter(
    key =>
      filterParams[key as keyof typeof filterParams] !== undefined &&
      filterParams[key as keyof typeof filterParams] !== '',
  ).length;

  return (
    <BaseContainer>
      <HeaderBase
        title={t('MY_JOBS')}
        titleStyle={styles.titleHeader}
        onPressBack={() => {
          NavigationService.goBack();
        }}
        rightActions={[
          {
            icon: (
              <Image source={playInstructionalVideos} style={styles.iconPlay} />
            ),
            onPress: handleOpenVideoInstructional,
          },
          {
            icon: (
              <View
                style={[
                  styles.iconCalendarContainer,
                  isFocusedGrantView && styles.iconCalendarActive,
                ]}
              >
                <Image source={calendar} style={styles.iconCalendar} />
              </View>
            ),
            onPress: handleGrantView,
          },
          {
            icon: (
              <SvgXml
                xml={IconFilter(
                  activeFilterCount > 0
                    ? colors.mainColorPrimary
                    : colors.grayScale70,
                )}
                width={24}
                height={24}
              />
            ),
            onPress: handleFilterPress,
          },
        ]}
        backgroundColor={colors.white}
      />
      {isFocusedGrantView ? (
        <GanttView />
      ) : (
        <TabView
          lazy
          swipeEnabled={false}
          navigationState={{ index, routes }}
          renderScene={renderScene}
          onIndexChange={setIndex}
          renderTabBar={renderTabBar}
          initialLayout={{ width: SCREEN_WIDTH }}
        />
      )}

      <FilterModal
        ref={filterModalRef}
        communities={(communitiesData || []).map((item: any) => ({
          id: item.id,
          name: item.name,
        }))}
        initialFilter={filterParams}
        onApply={handleApplyFilter}
        onReset={handleResetFilter}
        onClose={handleCloseFilter}
        setIsFocusedCalendar={setIsFocusedCalendar}
        rangeDate={rangeDate}
        setRangeDate={setRangeDate}
      />

      {isFocusedCalendar && (
        <CalenderPicker
          rangeDate={rangeDate}
          setRangeDate={setRangeDate}
          setIsFocusedCalendar={setIsFocusedCalendar}
        />
      )}

      <VideoSelectionModal
        ref={videoSelectionRef}
        onPlayVideo={video => {
          const redux = require('auth/redux');
          const currentLang = language || 'en';
          const videoUrl =
            video.url?.[currentLang as keyof typeof video.url] ||
            video.url?.en ||
            '';
          dispatch(
            redux.actionContainer.showVideoModal({
              initialSubtitle: currentLang,
              source: videoUrl,
              subtitle:
                video.subtitle?.[currentLang as keyof typeof video.subtitle] ||
                {},
              onClose: () => {
                dispatch(redux.actionContainer.hideVideoModal());
              },
            }),
          );
        }}
        onPlayAll={videos => {
          const redux = require('auth/redux');
          const currentLang = language || 'en';

          const playAtIndex = (idx: number) => {
            if (idx >= videos.length) return;
            const video = videos[idx];
            const videoUrl =
              video.url?.[currentLang as keyof typeof video.url] ||
              video.url?.en ||
              '';
            dispatch(
              redux.actionContainer.showVideoModal({
                initialSubtitle: currentLang,
                source: videoUrl,
                subtitle:
                  video.subtitle?.[
                    currentLang as keyof typeof video.subtitle
                  ] || {},
                onClose: () => {
                  dispatch(redux.actionContainer.hideVideoModal());
                  playAtIndex(idx + 1);
                },
              }),
            );
          };

          playAtIndex(0);
        }}
        videos={videoOptions as VideoOption[]}
      />
    </BaseContainer>
  );
}
