import React, { useState, useRef } from 'react';
import { View, ScrollView, TouchableOpacity } from 'react-native';
import { BaseContainer, HeaderBase, Text, SCREEN_WIDTH } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import Checklist from '../../components/Checklist';
import CommentChecklist from '../../components/CommentChecklist';
import useQIInspection from './useQIInspection';
import { NavigationService } from '../../services/NavigationService';
import { IconChevronDown, IconChevronUp } from '../../assets/svg';
import styles from './styles';

const QIInspectionScreen = () => {
  const { t } = useAppTranslation();
  const scrollViewRef = useRef<ScrollView>(null);
  const [isOpenChat, setIsOpenChat] = useState(true);

  const {
    checklists,
    qiStatusName,
    canRequestReInspect,
    handleRequestReinspect,
    isChecklistCompleted,
    QI_SCREEN_KEY,
  } = useQIInspection();

  const incompleteCount = checklists?.filter(
    (item: any) => !item.isChecked && item.isNA !== true,
  ).length ?? 0;

  return (
    <BaseContainer
      backgroundColor={colors.white}
      statusBarStyle="dark-content"
    >
      {/* Header — same as original: "Quality Inspector's Checklist" */}
      <HeaderBase
        title={t('QUANTITY_INSPECTION_CHECKLIST')}
        onPressBack={() => NavigationService.goBack()}
        backgroundColor={colors.white}
      />

      <View style={styles.content}>
        {/* QI Status text */}
        <Text style={styles.qiStatusText}>
          {t('QI_STATUS')}:{' '}
          <Text style={styles.qiStatusValue}>
            {qiStatusName || ''}
          </Text>
        </Text>

        {/* Red warning: "Please address X incomplete items." */}
        {incompleteCount > 0 && (
          <Text style={styles.incompleteWarning}>
            {t('PLEASE_ADDRESS')} {incompleteCount} {t('INCOMPLETE_ITEM')}
            {incompleteCount > 1 ? t('S') : ''}.
          </Text>
        )}

        {/* Scrollable content */}
        <ScrollView
          ref={scrollViewRef}
          style={styles.scrollView}
          showsVerticalScrollIndicator={false}
          keyboardShouldPersistTaps="handled"
          overScrollMode="always"
        >
          {/* Job Chat Group — collapsible section */}
          <View style={styles.chatContainer}>
            <TouchableOpacity
              style={styles.headerChat}
              onPress={() => setIsOpenChat(!isOpenChat)}
              activeOpacity={0.7}
            >
              <Text style={styles.titleChat}>
                {t('GROUP_CHAT')}
              </Text>
              <SvgXml
                xml={isOpenChat ? IconChevronUp(colors.black) : IconChevronDown(colors.black)}
                width={SCREEN_WIDTH * 0.06}
                height={SCREEN_WIDTH * 0.06}
              />
            </TouchableOpacity>

            {/* TODO: ChatContainer integration — requires ChatContainer component */}
            {/* {isOpenChat && (
              <ChatContainer chatId={workOrderChat?.id || ''} />
            )} */}
          </View>

          {/* Checklist items — reuse existing Checklist component */}
          <Checklist screenKey={QI_SCREEN_KEY} />
        </ScrollView>
      </View>

      {/* Bottom: Request Reinspect button — only when canRequestReInspect */}
      {canRequestReInspect && (
        <View style={styles.bottomContainer}>
          <TouchableOpacity
            style={[
              styles.reinspectButton,
              !isChecklistCompleted && styles.reinspectButtonDisabled,
            ]}
            onPress={handleRequestReinspect}
            activeOpacity={0.7}
          >
            <Text style={styles.reinspectButtonText}>
              {t('REQUEST_REINSPECT')}
            </Text>
          </TouchableOpacity>
        </View>
      )}

      {/* Comment modal — reuse existing CommentChecklist */}
      <CommentChecklist />
    </BaseContainer>
  );
};

export default QIInspectionScreen;
