import React, { useMemo, useRef } from 'react';
import { View } from 'react-native';
import BottomSheet, { BottomSheetView } from '@gorhom/bottom-sheet';
import { Button, Text } from 'tradewize-component';
import { useAppTranslation } from '../../../hooks/useAppTranslation';
import { logger } from '../../../utils';
import { styles } from '../styles';

const FilterBottomSheet = () => {
  const { t } = useAppTranslation();
  const bottomSheetRef = useRef<BottomSheet>(null);
  const snapPoints = useMemo(() => ['50%', '75%'], []);

  const handleClose = () => {
    bottomSheetRef.current?.close();
  };

  const handleClearAll = () => {
    logger('Clear all filters');
  };

  const handleApply = () => {
    logger('Apply filters');
    handleClose();
  };

  return (
    <BottomSheet
      ref={bottomSheetRef}
      index={-1}
      snapPoints={snapPoints}
      enablePanDownToClose
      onClose={handleClose}
      backgroundStyle={styles.bottomSheetBackground}
      containerStyle={styles.bottomSheetContainer}
    >
      <BottomSheetView style={styles.bottomSheetContent}>
        <View style={styles.filterContainer}>
          <View style={styles.content}>
            <Text style={styles.descriptionText}>{t('FILTER')}</Text>
          </View>

          <View style={styles.footer}>
            <Button style={styles.clearButton} onPress={handleClearAll}>
              <Text style={styles.clearButtonText}>{t('CLEAR_ALL')}</Text>
            </Button>
            <Button style={styles.applyButton} onPress={handleApply}>
              <Text style={styles.applyButtonText}>{t('APPLY')}</Text>
            </Button>
          </View>
        </View>
      </BottomSheetView>
    </BottomSheet>
  );
};

export default React.memo(FilterBottomSheet);
