import i18n from '../../i18n';
import { NavigationService } from '../../services/NavigationService';
import { SCREEN_ENUM } from '../../types/global';

const getHousePlanActiveByScheduleActivity =
  '/api/schedule-activities/get-house-plan-active-by-schedule-activty';
const getFileFromPresignUrl = '/api/files/presigned-url';

export const getPdfFile = async (scheduleActivityId: string = '') => {
  const redux = await import('auth/redux');
  const client = await import('auth/api');

  try {
    redux.store.dispatch(redux.actionContainer.showLoadingOverlay());
    const res = await client.getRequest(
      `${getHousePlanActiveByScheduleActivity}/${scheduleActivityId}`,
    );

    if (res.status !== 200) {
      return redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          title: i18n?.t('ERROR'),
          message: res.problem || 'Error',
          type: 'error',
        }),
      );
    }

    if (!Array.isArray(res?.data) || res?.data?.length === 0) {
      return redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          title: i18n?.t('ERROR'),
          message: i18n?.t('NO_DATA'),
          type: 'error',
        }),
      );
    }

    const findPdf = res?.data?.find((item: any) =>
      item?.fileExtension?.includes('.pdf'),
    );

    if (!findPdf?.key) {
      return redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          title: i18n?.t('ERROR'),
          message: i18n?.t('PDF_NOT_FOUND'),
          type: 'error',
        }),
      );
    }

    const encodedKey = encodeURIComponent(findPdf.key);
    const getFileFrom = await client.getRequest(
      `${getFileFromPresignUrl}/${encodedKey}`,
    );

    if (getFileFrom.status === 200 && getFileFrom?.data) {
      NavigationService.navigate(SCREEN_ENUM.PdfViewScreen, {
        pdfUrl: getFileFrom.data,
      });
    } else {
      return redux.store.dispatch(
        redux.actionContainer.showAlertAsync({
          title: i18n?.t('ERROR'),
          message: i18n?.t('FILE_DOWNLOAD_FAILED'),
          type: 'error',
        }),
      );
    }
  } catch (error: any) {
    return redux.store.dispatch(
      redux.actionContainer.showAlertAsync({
        title: i18n?.t('ERROR'),
        message: error?.message || 'UNKNOWN_ERROR',
        type: 'error',
      }),
    );
  } finally {
    redux.store.dispatch(redux.actionContainer.hideLoadingOverlay());
  }
};
