import React, { useMemo, useState } from 'react';
import {
  View,
  StyleSheet,
  Image,
  Alert,
  ScrollView,
  Platform,
} from 'react-native';
import { useTranslation } from 'react-i18next';
import { Text, Button, Input } from 'tradewize-component';
import { ActivityIndicator } from 'react-native-paper';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../theme';
import { IconTrash } from '../../assets/svg';

interface PhotoAttachment {
  uri?: string;
  fileName?: string;
  type?: string;
  direction?: string;
  area?: string;
  fileSize?: number;
}

interface ModalReportProgressProps {
  scrollViewRef?: React.RefObject<ScrollView>;
  photos: PhotoAttachment[];
  uploadResults: any[];
  isUploading: boolean;
  onCameraPress: (direction: string, area: string) => void;
  onRemovePhoto: (index: number) => void;
  onAreaChange: (index: number, area: string) => void;
  comment: string;
  onCommentChange: (text: string) => void;
  canEdit: boolean;
  helperView?: React.ReactNode;
  onFocus?: () => void;
  onBlur?: () => void;
}

export default function ModalReportProgress({
  scrollViewRef,
  photos,
  //   uploadResults,
  isUploading,
  onCameraPress,
  onRemovePhoto,
  onAreaChange,
  comment,
  onCommentChange,
  canEdit,
  helperView,
  onFocus,
  onBlur,
}: ModalReportProgressProps) {
  const { t } = useTranslation();
  const [selectedDirection, setSelectedDirection] = useState<string | null>(
    null,
  );

  const directionOptions = useMemo(
    () => [
      { label: t('NORTH_FACING'), value: 'north' },
      { label: t('SOUTH_FACING'), value: 'south' },
      { label: t('EAST_FACING'), value: 'east' },
      { label: t('WEST_FACING'), value: 'west' },
    ],
    [t],
  );

  const resetMetaForm = () => {
    setSelectedDirection(null);
  };

  const handleTakePhotoPress = () => {
    if (isUploading || photos.length >= 5) return;
    if (!selectedDirection) {
      Alert.alert(t('PLEASE_SELECT_WALL'), t('PLEASE_SELECT_WALL_MESSAGE'));
      return;
    }
    const directionValue = selectedDirection;
    resetMetaForm();
    onCameraPress(directionValue, '');
  };

  return (
    <>
      {/* Directions */}
      <View style={styles.directionOptionsWrapper}>
        {directionOptions.map(option => {
          const isSelected = selectedDirection === option.value;
          return (
            <Button
              variant="ghost"
              key={option.value}
              style={[
                styles.directionOption,
                isSelected && styles.directionOptionSelected,
              ]}
              onPress={() => setSelectedDirection(option.value)}
            >
              <Text
                style={[
                  styles.directionOptionText,
                  isSelected && styles.directionOptionTextSelected,
                ]}
              >
                {option.label}
              </Text>
            </Button>
          );
        })}
      </View>

      {/* Photos input */}
      <View style={styles.photosContainer}>
        <View style={styles.photosRow}>
          <Button
            variant="ghost"
            style={[
              styles.photoButton,
              (photos.length >= 5 || isUploading) && styles.disabledButton,
            ]}
            onPress={handleTakePhotoPress}
            disabled={isUploading || photos.length >= 5}
          >
            {isUploading ? (
              <ActivityIndicator size="small" color={colors.mainColorPrimary} />
            ) : (
              <View style={styles.photoButtonContent}>
                <Text style={styles.plusIcon}>+</Text>
                <Text
                  style={[
                    styles.photoButtonText,
                    (photos.length >= 5 || isUploading) &&
                      styles.disabledButtonText,
                  ]}
                >
                  {t('TAKE_PHOTOS')}
                </Text>
              </View>
            )}
          </Button>
        </View>
        <View style={styles.photoList}>
          {photos?.map((photo, index) => {
            const directionLabel = directionOptions.find(
              opt => opt.value === photo.direction,
            )?.label;
            const directionAreaLabel =
              photo.direction && photo.area
                ? `${directionLabel || photo.direction}`
                : directionLabel;
            return (
              <View key={index} style={styles.photoItem}>
                <Image
                  source={{ uri: photo.uri }}
                  style={styles.photoThumbnail}
                />
                <View style={styles.photoDetails}>
                  {(photo.direction || photo.area) && (
                    <View style={styles.directionBadge}>
                      <Text style={styles.directionBadgeText}>
                        {directionAreaLabel}
                      </Text>
                    </View>
                  )}
                  <View style={styles.areaInputWrapper}>
                    <Text style={styles.areaInputLabel}>{t('SQUARES')}:</Text>
                    <Input
                      editable={canEdit}
                      value={photo.area || ''}
                      onChangeText={(text: string) =>
                        onAreaChange(
                          index,
                          text
                            .replace(/,/g, '.') // đổi dấu , thành .
                            .replace(/[^0-9.]/g, '') // chỉ cho nhập số và dấu .
                            .replace(/(\..*)\./g, '$1') // chặn nhập nhiều dấu .
                            .replace(/^\./, '') // CHẶN dấu . ở đầu → ký tự đầu phải là số
                            .replace(/^(\d+\.?\d{0,2}).*$/, '$1'), // giữ tối đa 2 số thập phân
                        )
                      }
                      onFocus={() => {
                        onFocus?.();
                      }}
                      onBlur={() => {
                        onBlur?.();
                      }}
                      inputStyle={styles.areaInput}
                      inputContainerStyle={styles.areaInput}
                      placeholder={t('ENTER_SQUARES')}
                      keyboardType="numeric"
                    />
                  </View>
                </View>
                <Button
                  variant="ghost"
                  style={styles.removeButton}
                  onPress={() => onRemovePhoto(index)}
                >
                  <SvgXml xml={IconTrash(colors.red)} width={18} height={18} />
                </Button>
              </View>
            );
          })}
        </View>
      </View>

      {helperView}

      {/* Note input */}
      <View style={styles.commentContainer}>
        <Text style={styles.commentLabel}>{t('NOTE')}:</Text>
        <Input
          editable={canEdit}
          value={comment}
          onChangeText={onCommentChange}
          placeholder={t('ENTER_NOTE')}
          onFocus={() => {
            onFocus?.();
            if (Platform.OS === 'ios') {
              setTimeout(() => {
                scrollViewRef?.current?.scrollToEnd({
                  animated: true,
                });
              }, 150);
            }
          }}
          onBlur={() => {
            onBlur?.();
          }}
          multiline={true}
          numberOfLines={3}
          inputStyle={styles.commentInput}
          inputContainerStyle={styles.commentInput}
        />
      </View>
    </>
  );
}

