import { useMemo } from 'react';
import dayjs from 'dayjs';
import { useSelector } from 'react-redux';

export interface GanttEvent {
  id: string;
  title: string;
  startTime: string;
  endTime: string;
  location?: string;
  participants?: string[];
  color: string;
  status: number;
  originalData?: any;
}

const getEventColor = (status: number): string => {
  switch (status) {
    case 0:
      return '#fff';
    case 1:
      return '#50C878';
    case 2:
      return '#808080';
    default:
      return '#9B9B9B';
  }
};

const getEventTitle = (data: any): string => {
  if (data.clientName) {
    return `${data.clientName} - ${data.communityName || data.houseNumber}`;
  }
  return data.communityName || data.houseNumber || 'Unknown Job';
};

const getEventLocation = (data: any): string => {
  const parts = [];
  if (data.street) parts.push(data.street);
  if (data.city) parts.push(data.city);
  if (data.state) parts.push(data.state);
  return parts.join(', ');
};

const transformJobToGanttEvent = (
  job: any,
  jobType: 'NotStarted' | 'InProgress' | 'Completed',
): GanttEvent => {
  const startDate = job.estStartDate || job.actualStartDate;
  const endDate = job.estEndDate || job.actualEndDate;

  const startTime = startDate ? dayjs(startDate).format('HH:mm') : '09:00';
  const endTime = endDate ? dayjs(endDate).format('HH:mm') : '17:00';

  const getStatusFromJobType = (type: string): number => {
    switch (type) {
      case 'NotStarted':
        return 0;
      case 'InProgress':
        return 1;
      case 'Completed':
        return 2;
      default:
        return 0;
    }
  };

  const status = getStatusFromJobType(jobType);
  const color = getEventColor(status);

  return {
    id: job.workOrderId || job.id,
    title: getEventTitle(job),
    startTime,
    endTime,
    location: getEventLocation(job),
    participants: job.companyName ? [job.companyName] : [],
    color: color,
    status: status,
    originalData: job,
  };
};

export const useGanttData = () => {
  const ganttData = useSelector((state: any) => state.myjob.ganttData);

  const ganttEvents = useMemo(() => {
    const notStartedJobs = (ganttData.data.notStarted || []).map((job: any) =>
      transformJobToGanttEvent(job, 'NotStarted'),
    );
    const inProgressJobs = (ganttData.data.inProgress || []).map((job: any) =>
      transformJobToGanttEvent(job, 'InProgress'),
    );
    const completedJobs = (ganttData.data.completed || []).map((job: any) =>
      transformJobToGanttEvent(job, 'Completed'),
    );

    const allJobs = [...notStartedJobs, ...inProgressJobs, ...completedJobs];

    return allJobs;
  }, [ganttData.data]);

  const isLoading = ganttData.loading;

  return {
    events: ganttEvents,
    loading: isLoading,
  };
};
