import React from 'react';
import {
  View,
  ScrollView,
  Image,
  KeyboardAvoidingView,
  Platform,
} from 'react-native';
import {
  Text,
  Button,
  Input,
  BaseContainer,
  HeaderBase,
} from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { ActivityIndicator } from 'react-native-paper';
import { SCREEN_WIDTH } from '@gorhom/bottom-sheet';
import { IconPen } from '../../assets/svg';
import { colors } from '../../theme';
import { styles } from './styles';
import { useInstallationProgress } from './useInstallationProgress';
import ModalReportProgress from './ModalReportProgress';
import ProgressCircle from './components/ProgressCircle';
import HistoryModal from './components/HistoryModal';
import ImageViewerModal from './components/ImageViewerModal';
import EditModal from './components/EditModal';
import { NavigationService } from '../../services/NavigationService';

export default function ReportProgress() {
  const hook = useInstallationProgress();
  const {
    t,
    insets,
    jobData,
    sqftInstalled,
    totalSqft,
    initialSqft,
    keyboardOffset,
    photos,
    uploadResults,
    isUploading,
    isSubmitting,
    installationData,
    loading,
    error,
    isFocused,
    errorSqft,
    isShowBtn,
    comment,
    showHistoryModal,
    selectedImageUrl,
    hasSubmittedToday,
    showEditModal,
    editModalSqft,
    editModalPhotos,
    editModalUploadResults,
    editModalComment,
    editModalErrorSqft,
    progressHistoryData,
    canEdit,
    progressPercentage,
    scrollViewRef,
    editModalScrollViewRef,
    setKeyboardOffset,
    setIsFocused,
    setComment,
    setShowHistoryModal,
    setSelectedImageUrl,
    setShowEditModal,
    setEditModalSqft,
    setEditModalPhotos,
    setEditModalUploadResults,
    setEditModalComment,
    setEditModalErrorSqft,
    setError,
    setLoading,
    handleSqftChange,
    handleEditModalSqftChange,
    handleCameraPicker,
    handleRemovePhoto,
    handlePhotoAreaChange,
    handleEditModalPhotoUpload,
    handleEditModalPhotoAreaChange,
    handleUpdate,
    handleClose,
  } = hook;

  // Loading state
  if (loading) {
    return (
      <View style={styles.container}>
        <View style={styles.loadingContainer}>
          <ActivityIndicator size="large" color={colors.mainColorPrimary} />
        </View>
      </View>
    );
  }

  // Error state
  if (error) {
    return (
      <View style={styles.container}>
        <View style={styles.errorContainer}>
          <Text style={styles.textErrorMedium}>{error}</Text>
          <Button
            onPress={() => {
              setError(null);
              setLoading(true);
            }}
            variant="primary"
            style={styles.retryButton}
          >
            <Text style={styles.textBoldMediumWhite}>{t('RETRY')}</Text>
          </Button>
        </View>
      </View>
    );
  }

  return (
    <BaseContainer
      backgroundStatusBarColor={colors.white}
      backgroundColor={colors.white}
      style={styles.container}
    >
      <HeaderBase
        title={t('REPORT_JOB_PROGRESS')}
        onPressBack={() => NavigationService.goBack()}
      />
      <KeyboardAvoidingView
        keyboardVerticalOffset={keyboardOffset}
        style={{ flex: 1 }}
        behavior="height"
      >
        <ScrollView
          ref={scrollViewRef}
          style={styles.content}
          showsVerticalScrollIndicator={false}
        >
          {/* Job Info */}
          <View style={styles.jobInfoRow}>
            <View style={styles.jobInfoContainer}>
              <Text style={styles.jobTitle}>
                {t('JOB_REPORT')} {installationData?.communityCode}/
                {installationData?.lotNumber}
              </Text>
              <Text style={styles.address}>
                {t('ADDRESS')}: {installationData?.address || jobData?.address}
              </Text>
            </View>
          </View>

          {/* Input Section */}
          <View style={[styles.inputSectionBorder, { paddingBottom: 12 }]}>
            {/* Display current/total squares */}
            <View
              style={{
                marginTop: 12,
                justifyContent: 'center',
                alignItems: 'center',
              }}
            >
              <View
                style={{
                  borderWidth: 1,
                  borderColor: '#E5E5E5',
                  borderRadius: 12,
                  padding: 8,
                  width: SCREEN_WIDTH - 72,
                }}
              >
                <View style={styles.sqftDisplayContainer}>
                  <Text style={styles.sqftDisplayLabel}>
                    {t('INSTALLED_TOTAL_SQUARES')}:
                  </Text>
                  <Text style={styles.textMediumMedium}>
                    {initialSqft || '0'}/{totalSqft}
                  </Text>
                </View>

                {/* Display remaining squares */}
                {isShowBtn && (
                  <View style={styles.sqftDisplayContainer}>
                    <Text style={styles.sqftDisplayLabel}>
                      {t('REMAINING_SQUARES')}:
                    </Text>
                    <Text style={styles.textMediumMedium}>
                      {installationData?.remainingSqft?.toFixed(2) || '0.00'}
                    </Text>
                  </View>
                )}
              </View>
            </View>

            {/* Submitted data (read-only) when already submitted today */}
            {canEdit && isShowBtn && hasSubmittedToday && (
              <View style={styles.submittedDataContainer}>
                <View style={styles.submittedDataRow}>
                  <Text style={styles.submittedDataLabel}>
                    {t('TODAYS_INSTALLED_SQUARES') ||
                      "Today's Installed Squares"}
                    :
                  </Text>
                  <Text style={styles.submittedDataValue}>
                    {sqftInstalled || '0.00'}
                  </Text>
                  <Button
                    variant="ghost"
                    onPress={() => {
                      setEditModalSqft('');
                      setEditModalPhotos([]);
                      setEditModalUploadResults([]);
                      setEditModalComment('');
                      setEditModalErrorSqft(null);
                      setShowEditModal(true);
                    }}
                    style={styles.editIconButton}
                  >
                    <SvgXml
                      xml={IconPen(colors.mainColorPrimary)}
                      width={20}
                      height={20}
                    />
                  </Button>
                </View>

                {/* Photos - Read Only */}
                {photos && photos.length > 0 && (
                  <View style={styles.submittedPhotosContainer}>
                    <Text style={styles.submittedDataLabel}>
                      {t('PHOTOS') || 'Photos'}:
                    </Text>
                    <View style={styles.submittedPhotoList}>
                      {photos.map((photo, index) => (
                        <View key={index} style={styles.submittedPhotoItem}>
                          <Image
                            source={{ uri: photo.uri }}
                            style={styles.submittedPhotoThumbnail}
                          />
                        </View>
                      ))}
                    </View>
                  </View>
                )}

                {/* Note - Read Only */}
                {comment && comment.trim() !== '' && (
                  <View style={styles.submittedNoteContainer}>
                    <Text
                      style={[
                        styles.submittedDataLabel,
                        styles.submittedNoteLabel,
                      ]}
                    >
                      {t('NOTE')}:
                    </Text>
                    <Text
                      style={[
                        styles.submittedDataValue,
                        styles.submittedNoteText,
                      ]}
                    >
                      {comment || 'No note'}
                    </Text>
                  </View>
                )}
              </View>
            )}

            {/* Photos and Note input - Only when not submitted today */}
            {canEdit && isShowBtn && !hasSubmittedToday && (
              <ModalReportProgress
                scrollViewRef={scrollViewRef as React.RefObject<ScrollView>}
                helperView={
                  <>
                    <View style={styles.errorSqftContainer}>
                      <Text style={styles.errorSqft}>{errorSqft}</Text>
                    </View>
                    <View
                      style={[
                        styles.sqftInputRow,
                        { width: '95%', alignSelf: 'center', marginTop: 12 },
                      ]}
                    >
                      <Text style={styles.sqftRowLabel}>
                        {t('TOTAL_INSTALLED_SQUARES')}:
                      </Text>
                      <Input
                        editable={false}
                        value={sqftInstalled}
                        onChangeText={handleSqftChange}
                        keyboardType="numeric"
                        inputStyle={styles.sqftInput}
                        inputContainerStyle={styles.sqftInput}
                        placeholder="0.00"
                        onFocus={() => {
                          setKeyboardOffset(Platform.OS === 'ios' ? 12 : 56);
                          setIsFocused(true);
                        }}
                        onBlur={() => {
                          setKeyboardOffset(0);
                          setIsFocused(false);
                        }}
                      />
                    </View>
                  </>
                }
                onFocus={() => {
                  setKeyboardOffset(Platform.OS === 'ios' ? 12 : 56);
                  setIsFocused(true);
                }}
                onBlur={() => {
                  setKeyboardOffset(0);
                  setIsFocused(false);
                }}
                photos={photos}
                uploadResults={uploadResults}
                isUploading={isUploading}
                onCameraPress={handleCameraPicker}
                onRemovePhoto={handleRemovePhoto}
                onAreaChange={handlePhotoAreaChange}
                comment={comment}
                onCommentChange={setComment}
                canEdit={canEdit}
              />
            )}
          </View>

          {/* Progress Circle */}
          <ProgressCircle progressPercentage={progressPercentage} />
        </ScrollView>

        {/* Bottom Buttons */}
        {isShowBtn && canEdit && !hasSubmittedToday && (
          <View
            style={[
              styles.bottomButtons,
              !isFocused && { paddingBottom: insets.bottom },
            ]}
          >
            {!isSubmitting && (
              <Button
                onPress={handleClose}
                variant="secondary"
                style={[styles.button, styles.closeButton]}
              >
                <Text style={styles.textBoldMediumBlack}>{t('CLOSE')}</Text>
              </Button>
            )}

            <Button
              onPress={() => handleUpdate()}
              disabled={isSubmitting}
              variant="primary"
              style={[
                styles.button,
                styles.updateButton,
                isSubmitting && styles.buttonFullWidth,
              ]}
            >
              <Text style={styles.textBoldMediumWhite}>
                {isSubmitting ? t('SUBMITTING') : t('SUBMIT')}
              </Text>
            </Button>
          </View>
        )}
      </KeyboardAvoidingView>

      {/* History Modal */}
      <HistoryModal
        visible={showHistoryModal}
        historyData={progressHistoryData}
        onClose={() => setShowHistoryModal(false)}
        onImagePress={setSelectedImageUrl}
        t={t}
      />

      {/* Full Screen Image Viewer */}
      <ImageViewerModal
        imageUrl={selectedImageUrl}
        onClose={() => setSelectedImageUrl(null)}
      />

      {/* Edit Modal */}
      <EditModal
        visible={showEditModal}
        onClose={() => setShowEditModal(false)}
        editModalSqft={editModalSqft}
        editModalPhotos={editModalPhotos}
        editModalUploadResults={editModalUploadResults}
        editModalComment={editModalComment}
        editModalErrorSqft={editModalErrorSqft}
        isUploading={isUploading}
        isSubmitting={isSubmitting}
        canEdit={canEdit}
        maxTodaySqft={hook.maxTodaySqft}
        progressPercentage={progressPercentage}
        scrollViewRef={editModalScrollViewRef}
        setEditModalSqft={setEditModalSqft}
        setEditModalPhotos={setEditModalPhotos}
        setEditModalUploadResults={setEditModalUploadResults}
        setEditModalComment={setEditModalComment}
        setEditModalErrorSqft={setEditModalErrorSqft}
        setKeyboardOffset={setKeyboardOffset}
        setIsFocused={setIsFocused}
        handleEditModalSqftChange={handleEditModalSqftChange}
        handleEditModalPhotoUpload={handleEditModalPhotoUpload}
        handleEditModalPhotoAreaChange={handleEditModalPhotoAreaChange}
        handleUpdate={handleUpdate}
        checkPermission={hook.checkPermission}
        t={t}
      />
    </BaseContainer>
  );
}
