import { useCallback, useEffect, useRef, useState } from 'react';
import { useDispatch, useSelector } from 'react-redux';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { logger } from '../../utils';
import { getInspectionRequest, registerJobs } from '../../api/endpoint';
import { InspectionRequest } from './types';
import { NavigationService } from '../../services/NavigationService';
import { SCREEN_ENUM } from '../../types/global';

const PAGE_SIZE = 10;

/** Sort items so bonus items appear first */
const sortByBonus = (items: InspectionRequest[]): InspectionRequest[] => {
  return [...items].sort((a, b) => {
    const aHasBonus = a.bonusAmount != null && a.bonusAmount > 0;
    const bHasBonus = b.bonusAmount != null && b.bonusAmount > 0;
    if (aHasBonus && !bHasBonus) return -1;
    if (!aHasBonus && bHasBonus) return 1;
    return 0;
  });
};

export const useInspectionRequests = () => {
  const { t } = useAppTranslation();
  const dispatch = useDispatch();

  const isLoading = useSelector(
    (state: any) => state.app.loadingOverlay?.isVisible,
  );
  const profileData = useSelector((state: any) => state.auth?.userProfile);

  // ---------- State ----------
  const [inspectionRequests, setInspectionRequests] = useState<
    InspectionRequest[]
  >([]);
  const [selectedItems, setSelectedItems] = useState<Set<string>>(new Set());
  const [pageIndex, setPageIndex] = useState(1);
  const [loadingMore, setLoadingMore] = useState(false);
  const [refreshing, setRefreshing] = useState(false);
  const [hasMore, setHasMore] = useState(true);

  // Use ref to avoid stale closure in fetchInspectionRequests
  const pageIndexRef = useRef(pageIndex);
  pageIndexRef.current = pageIndex;

  // ---------- Data Fetching ----------
  const fetchInspectionRequests = useCallback(async () => {
    const redux = await import('auth/redux');
    const client = await import('auth/api');
    const currentPage = pageIndexRef.current;

    try {
      if (currentPage === 1) {
        dispatch(redux.actionContainer.showLoadingOverlay());
      } else {
        setLoadingMore(true);
      }

      const response = await client.getRequest(
        `${getInspectionRequest}?PageIndex=${currentPage}&PageSize=${PAGE_SIZE}&SortBy=bonusAmount`,
      );

      if (response?.data?.items) {
        const sortedItems = sortByBonus(response.data.items);

        if (currentPage === 1) {
          setInspectionRequests(sortedItems);
        } else {
          setInspectionRequests(prev => [...prev, ...sortedItems]);
        }

        setHasMore(response.data.totalPage > currentPage);
      }
    } catch (error) {
      logger('Error fetching inspection requests:', error);
    } finally {
      setRefreshing(false);
      if (currentPage === 1) {
        dispatch(redux.actionContainer.hideLoadingOverlay());
      } else {
        setLoadingMore(false);
      }
    }
  }, [dispatch]);

  // ---------- Handlers ----------
  const handleLoadMore = useCallback(() => {
    if (!loadingMore && !refreshing && !isLoading && hasMore) {
      setPageIndex(prev => prev + 1);
    }
  }, [loadingMore, refreshing, isLoading, hasMore]);

  const handleRefresh = useCallback(() => {
    setRefreshing(true);
    setPageIndex(1);
    setSelectedItems(new Set());
    fetchInspectionRequests();
  }, [fetchInspectionRequests]);

  const handleItemPress = useCallback((itemId: string) => {
    setSelectedItems(prev => {
      const newSet = new Set(prev);
      if (newSet.has(itemId)) {
        newSet.delete(itemId);
      } else {
        newSet.add(itemId);
      }
      return newSet;
    });
  }, []);

  const handleRegister = useCallback(async () => {
    const redux = await import('auth/redux');
    const client = await import('auth/api');

    if (profileData?.isDueTraining || profileData?.needWatchVideoNow) {
      dispatch(
        redux.actionContainer.showAlertAsync({
          type: 'warning',
          title: t('WARNING'),
          message: t('YOU_NEED_DONE_DUE_VIDEOS_TO_KEEP_GOING'),
          buttonText: t('GO_TO_VIDEOS_NOW'),
          isBackdropPress: false,
          onClose: () => {
            dispatch(redux.actionContainer.hideAlertAsync());
            setTimeout(() => {
              NavigationService.navigate(SCREEN_ENUM.SystemQualityGuideScreen);
            }, 350);
          },
        }),
      );
      return;
    }

    if (selectedItems.size === 0) {
      dispatch(
        redux.actionContainer.showAlertAsync({
          type: 'warning',
          title: t('WARNING'),
          message: t('PLEASE_SELECT_JOB_TO_REGISTER'),
          buttonText: t('OK'),
        }),
      );
      return;
    }

    try {
      dispatch(redux.actionContainer.showLoadingOverlay());
      const response = await client.postRequest(registerJobs, {
        jobIds: Array.from(selectedItems),
      });

      if (response?.status === 200) {
        dispatch(
          redux.actionContainer.showAlertAsync({
            type: 'success',
            title: t('SUCCESS'),
            message: t('REGISTER_JOB_SUCCESSFULLY'),
            buttonText: t('OK'),
            onClose: () => {
              dispatch(redux.actionContainer.hideAlertAsync());
              handleRefresh();
            },
          }),
        );
      } else {
        dispatch(
          redux.actionContainer.showAlertAsync({
            type: 'warning',
            title: t('WARNING'),
            message: response?.data?.message ?? t('REGISTER_JOB_FAILED'),
            buttonText: t('OK'),
          }),
        );
      }
    } catch (error) {
      logger('Error registering inspection requests:', error);
      dispatch(
        redux.actionContainer.showAlertAsync({
          type: 'warning',
          title: t('WARNING'),
          message: t('SOMETHING_WENT_WRONG'),
          buttonText: t('OK'),
        }),
      );
    } finally {
      dispatch(redux.actionContainer.hideLoadingOverlay());
    }
  }, [dispatch, t, profileData, selectedItems, handleRefresh]);

  // ---------- Effects ----------
  useEffect(() => {
    fetchInspectionRequests();
  }, [pageIndex, fetchInspectionRequests]);

  return {
    // State
    inspectionRequests,
    selectedItems,
    loadingMore,
    refreshing,
    isLoading,
    hasMore,

    // Handlers
    handleLoadMore,
    handleRefresh,
    handleItemPress,
    handleRegister,
  };
};
