import { View } from 'react-native';
import {
  BaseContainer,
  HeaderBase,
  SCREEN_WIDTH,
  Text,
} from 'tradewize-component';
import { styles } from './styles';
import { colors } from '../../theme';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { SvgXml } from 'react-native-svg';
import { IconExportPdf } from '../../assets/svg';
import { ShadowedView } from 'react-native-fast-shadow';
import { shadowGlobal } from '../../types/global';
import { NavigationService } from '../../services/NavigationService';
import { useRoute } from '@react-navigation/native';
import Pdf from 'react-native-pdf';
import { downloadPdfBlobUtil } from './helper';

const PdfViewScreen = () => {
  const route = useRoute();
  const { pdfUrl } = route.params as { pdfUrl: string };

  const { t } = useAppTranslation();

  return (
    <BaseContainer
      style={styles.container}
      backgroundColor={colors.colorF0F0F0}
      backgroundStatusBarColor={colors.white}
    >
      <HeaderBase
        title={t('PREVIEW_PDF')}
        onPressBack={() => NavigationService.goBack()}
        rightActions={[
          {
            icon: (
              <ShadowedView style={[styles.iconContainer, shadowGlobal]}>
                <SvgXml
                  xml={IconExportPdf()}
                  width={SCREEN_WIDTH * 0.06}
                  height={SCREEN_WIDTH * 0.06}
                />
              </ShadowedView>
            ),
            onPress: () => {
              if (pdfUrl) {
                downloadPdfBlobUtil(pdfUrl);
              }
            },
          },
        ]}
      />
      {pdfUrl && (
        <Pdf
          trustAllCerts={false}
          source={{ uri: pdfUrl }}
          style={styles.pdf}
        />
      )}
    </BaseContainer>
  );
};

export default PdfViewScreen;
