import { View } from 'react-native';
import { useAppTranslation } from '../../hooks/useAppTranslation';
import { useDispatch, useSelector } from 'react-redux';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { logger } from '../../utils';
import { useRoute } from '@react-navigation/native';
import {
  BaseContainer,
  BottomSelector,
  Button,
  HeaderBase,
  Text,
} from 'tradewize-component';
import type { BottomSelectorOption } from 'tradewize-component';
import { NavigationService } from '../../services/NavigationService';
import { FlashList } from '@shopify/flash-list';
import { styles } from './styles';

export interface Item {
  colorId: any;
  materialId: string;
  name: string;
  colorName: any;
  colorCode: any;
  materialName: string;
  unitTypeName: string;
  unitTypeCode: string;
  size: string;
  quantity: any;
  colors: Color[];
}

export interface Color {
  colorId: string;
  colorName: string;
  colorCode: string;
}

type SelectorField = 'quantity' | 'color';

const MaterialsWarranty = () => {
  const route = useRoute();
  const params = route?.params as { id: string };
  const dispatch = useDispatch();
  const { t } = useAppTranslation();

  const materialsWarranty = useSelector(
    (state: any) => state.myjob.materialsWarranty?.data,
  );

  // BottomSelector state
  const [isSelectorVisible, setIsSelectorVisible] = useState(false);
  const [selectorOptions, setSelectorOptions] = useState<
    BottomSelectorOption[]
  >([]);
  const [selectorTitle, setSelectorTitle] = useState('');
  const [activeField, setActiveField] = useState<SelectorField | null>(null);
  const [activeMaterialId, setActiveMaterialId] = useState<string | null>(null);

  // Generate quantity options (0 to maxQuantity)
  const generateQuantityOptions = (
    verifyQuantity: number,
    initialLabel?: string,
  ): BottomSelectorOption[] => {
    if (!verifyQuantity) return [];
    const options: BottomSelectorOption[] = [];
    const hasDecimal = verifyQuantity % 1 !== 0;
    const wholeNumber = Math.floor(verifyQuantity);

    // Add initial label option if provided
    if (initialLabel) {
      options.push({
        label: initialLabel,
        value: '0',
      });
    }

    if (hasDecimal) {
      // Generate options with 0.5 increments, starting from 1 if initialLabel exists
      const startValue = initialLabel ? 1 : 0;
      for (let i = startValue; i <= wholeNumber; i += 0.5) {
        options.push({
          label: i.toString(),
          value: i.toString(),
        });
      }

      // Add the exact verifyQuantity if it's not already included
      const lastOption = options[options.length - 1];
      if (lastOption && parseFloat(lastOption.value) !== verifyQuantity) {
        options.push({
          label: verifyQuantity.toString(),
          value: verifyQuantity.toString(),
        });
      }
    } else {
      // Original logic for whole numbers, starting from 1 if initialLabel exists
      const startValue = initialLabel ? 1 : 0;
      for (let i = startValue; i <= verifyQuantity; i++) {
        options.push({
          label: i.toString(),
          value: i.toString(),
        });
      }
    }

    return options;
  };

  // Open quantity selector
  const openQuantitySelector = useCallback(
    (materialId: string, maxQuantity: number) => {
      const options = generateQuantityOptions(maxQuantity, t('NO_NEED'));
      setSelectorOptions(options);
      setSelectorTitle(t('PLEASE_SELECT_RECEIVED_NUMBER'));
      setActiveField('quantity');
      setActiveMaterialId(materialId);
      setIsSelectorVisible(true);
    },
    [t],
  );

  // Build color options for a material item
  const getColorOptions = useCallback((item: Item): BottomSelectorOption[] => {
    return (item.colors || []).map(color => ({
      label: color.colorName,
      value: color.colorId,
    }));
  }, []);

  // Open color selector
  const openColorSelector = useCallback(
    (item: Item) => {
      const options = getColorOptions(item);
      setSelectorOptions(options);
      setSelectorTitle(t('PLEASE_SELECT_COLOR'));
      setActiveField('color');
      setActiveMaterialId(item.materialId);
      setIsSelectorVisible(true);
    },
    [getColorOptions, t],
  );

  // Handle selection from BottomSelector — update Redux directly
  const handleSelect = useCallback(
    async (option: BottomSelectorOption) => {
      const materialId = activeMaterialId;
      const field = activeField;

      // Close selector first
      setIsSelectorVisible(false);
      setActiveMaterialId(null);
      setActiveField(null);

      if (!materialId || !field) return;

      try {
        const redux = await import('auth/redux');
        if (field === 'quantity') {
          dispatch(
            redux.actionContainer.updateMaterialWarrantyItem({
              materialId,
              quantity: Number(option.value),
            }),
          );
        } else if (field === 'color') {
          dispatch(
            redux.actionContainer.updateMaterialWarrantyItem({
              materialId,
              colorId: option.value,
              colorName: option.label,
            }),
          );
        }
      } catch (error) {
        logger('MaterialsWarranty handleSelect', error);
      }
    },
    [activeMaterialId, activeField, dispatch],
  );

  const renderItem = ({ item }: { item: Item }) => {
    const quantityLabel =
      item.quantity !== undefined && item.quantity !== null
        ? item.quantity === 0
          ? t('NO_NEED')
          : item.quantity.toString()
        : undefined;
    const colorLabel = item.colorName || undefined;
    const colorOptions = getColorOptions(item);
    const hasColors = colorOptions.length > 0;

    return (
      <View style={styles.materialItemContainer}>
        <View style={styles.materialItem}>
          <View style={styles.materialInfo}>
            <Text style={styles.materialName} numberOfLines={2}>
              {item?.materialName || item?.name}
            </Text>

            <Text style={styles.materialDetails}>
              {`${t('SIZE')}: ${item.size} - ${t('U/M')}: ${item.unitTypeName}`}
            </Text>
            <Text style={styles.materialDetails}>
              {`${t('SKU')}: ${item.unitTypeCode}`}
            </Text>
          </View>
        </View>

        <View style={styles.toggleContainer}>
          {/* Quantity Selector Trigger */}
          <Button
            variant="ghost"
            style={styles.toggleWrapper}
            onPress={() => openQuantitySelector(item.materialId, item.quantity)}
          >
            <Text style={styles.selectorLabel}>{t('QUANTITY')}</Text>
            <View style={styles.selectedValueContainer}>
              <Text
                style={
                  quantityLabel
                    ? styles.selectedValueText
                    : styles.placeholderText
                }
              >
                {quantityLabel ?? t('PLEASE_SELECT_RECEIVED_NUMBER')}
              </Text>
            </View>
          </Button>

          {/* Color Selector Trigger */}
          {hasColors && (
            <Button
              variant="ghost"
              style={styles.toggleWrapper}
              onPress={() => openColorSelector(item)}
            >
              <Text style={styles.selectorLabel}>{t('COLOR')}</Text>
              <View style={styles.selectedValueContainer}>
                <Text
                  style={
                    colorLabel
                      ? styles.selectedValueText
                      : styles.placeholderText
                  }
                >
                  {colorLabel ?? t('PLEASE_SELECT_COLOR')}
                </Text>
              </View>
            </Button>
          )}
        </View>
      </View>
    );
  };

  // Get selected value for BottomSelector highlight
  const selectedValue = useMemo(() => {
    if (!activeMaterialId || !activeField) return undefined;
    const item = (materialsWarranty || []).find(
      (m: Item) => m.materialId === activeMaterialId,
    );
    if (!item) return undefined;
    if (activeField === 'quantity') {
      return item.quantity?.toString();
    }
    if (activeField === 'color') {
      return item.colorId;
    }
    return undefined;
  }, [activeMaterialId, activeField, materialsWarranty]);

  return (
    <BaseContainer>
      <HeaderBase
        title={t('MATERIALS')}
        onPressBack={() => NavigationService.goBack()}
      />

      <FlashList
        style={styles.flatlist}
        keyExtractor={(item: Item) => item?.materialId?.toString()}
        data={materialsWarranty || []}
        renderItem={renderItem}
      />

      {/* Quantity / Color Bottom Selector */}
      <BottomSelector
        title={selectorTitle}
        isVisible={isSelectorVisible}
        onClose={() => setIsSelectorVisible(false)}
        selectedValue={selectedValue}
        options={selectorOptions}
        onSelect={handleSelect}
        buttonCancelStyle={styles.buttonCancerSelect}
        buttonCancelTextStyle={styles.buttonCancerSelectText}
        cancelText={t('CLOSE')}
        emptyText={t('NO_DATA_FOUND')}
      />
    </BaseContainer>
  );
};

export default MaterialsWarranty;
