import React from 'react';
import { View, ScrollView, Image } from 'react-native';
import { Text, Button } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { IconClose } from '../../../assets/svg';
import { styles } from '../styles';
import { ProgressHistoryItem } from '../types';
import { formatDate, isImageFile } from '../helpers';

interface HistoryModalProps {
  visible: boolean;
  historyData: ProgressHistoryItem[];
  onClose: () => void;
  onImagePress: (url: string) => void;
  t: (key: string) => string;
}

const HistoryModal = React.memo(
  ({ visible, historyData, onClose, onImagePress, t }: HistoryModalProps) => {
    if (!visible) return null;

    return (
      <View style={styles.viewHistoryModal}>
        <View style={styles.modalOverlay}>
          <View style={styles.modalContainer}>
            {/* Modal Header */}
            <View style={styles.modalHeader}>
              <Text style={styles.modalTitle}>{t('JOB_PROGRESS_HISTORY')}</Text>
              <Button
                variant="ghost"
                onPress={onClose}
                style={styles.closeButtonModal}
              >
                <SvgXml
                  xml={IconClose()}
                  width={18}
                  height={18}
                  style={styles.closeButtonModal}
                />
              </Button>
            </View>

            {/* Dashed Line */}
            <View style={styles.dashedLine} />

            {/* History List */}
            <ScrollView style={styles.historyList}>
              {historyData.length > 0 ? (
                historyData.map(item => (
                  <View key={item.historyId} style={styles.historyItem}>
                    <Text style={styles.historyField}>
                      Date: {formatDate(item.updatedAt)}
                    </Text>

                    <Text style={styles.historyField}>
                      {t('SQUARES')}: {item.sqft} SQ
                    </Text>

                    <View style={styles.photosFieldContainer}>
                      <Text style={styles.historyField}>{t('PHOTOS')}:</Text>
                      {item.fileEntities && item.fileEntities.length > 0 ? (
                        <View style={styles.photosThumbnailsRow}>
                          {item.fileEntities.map(file => (
                            <View
                              key={file.fileId}
                              style={styles.photoThumbnailSmall}
                            >
                              {isImageFile(file.fileExtension) ? (
                                <Button
                                  variant="ghost"
                                  onPress={() => onImagePress(file.url)}
                                  style={styles.imageThumbnailTouchable}
                                >
                                  <Image
                                    source={{ uri: file.url }}
                                    style={styles.photoThumbnailSmallImage}
                                    resizeMode="cover"
                                  />
                                </Button>
                              ) : (
                                <View style={styles.fileIconSmall}>
                                  <Text style={styles.fileIconTextSmall}>
                                    {file.fileExtension?.toUpperCase() ||
                                      'FILE'}
                                  </Text>
                                </View>
                              )}
                            </View>
                          ))}
                        </View>
                      ) : (
                        <Text style={styles.historyFieldGray}>{t('NONE')}</Text>
                      )}
                    </View>

                    <Text style={styles.historyFieldBold}>
                      {t('NOTE')}: {item.note || ''}
                    </Text>

                    <Text style={styles.historyField}>
                      {t('REPORTED_BY')}: {item.updatedByName || 'Unknown'}
                    </Text>
                  </View>
                ))
              ) : (
                <View style={styles.emptyHistoryContainer}>
                  <Text style={styles.emptyHistoryText}>
                    {t('NO_PROGRESS_HISTORY_AVAILABLE')}
                  </Text>
                </View>
              )}
            </ScrollView>
          </View>
        </View>
      </View>
    );
  },
);

export default HistoryModal;
