import dayjs from 'dayjs';
import React, { useMemo } from 'react';
import { Image, StyleSheet, Text, View } from 'react-native';
import { SvgXml } from 'react-native-svg';
import { defaultJob, rating } from '../../../assets/images';
import { formatCurrency, formatMiles } from '../../../utils';
import { colors } from '../../../theme';
import { Button, SCREEN_WIDTH } from 'tradewize-component';
import {
  IconCheck,
  IconClock,
  IconEllipse,
  IconLocation,
} from '../../../assets/svg';
import { FORMAT_TIME_CLIENT_JOB_START } from '../../../types/global';
import { useAppTranslation } from '../../../hooks/useAppTranslation';
import { RequestItemProps } from '../types';

// ---------- Sub-components ----------

const BonusSection = React.memo(
  ({
    amount,
    bonusAmount,
    isCheck,
  }: {
    amount?: number;
    bonusAmount: number;
    isCheck: boolean;
  }) => {
    const { t } = useAppTranslation();

    return (
      <>
        <View style={styles.bonusContainer}>
          <Image source={rating} style={styles.statIcon} />
          <Text
            style={[
              styles.emergencyText,
              {
                color: isCheck ? colors.white : colors.twColors.text.darkGray,
              },
            ]}
          >
            {t('EMERGENCY')}:
          </Text>
          <View style={styles.flexFill} />
          <Text style={styles.bonusText}>
            ${amount} + ${bonusAmount} {t('BONUS')}
          </Text>
        </View>
        <View style={styles.divider} />
      </>
    );
  },
);

const CheckBox = React.memo(
  ({ isCheck, onPress }: { isCheck: boolean; onPress?: () => void }) => (
    <Button
      style={[styles.checkBox, isCheck && styles.checkedContainer]}
      onPress={onPress}
    >
      {isCheck && (
        <SvgXml
          xml={IconCheck(colors.twColors.primary)}
          width={16}
          height={16}
        />
      )}
    </Button>
  ),
);

const DistanceInfo = React.memo(
  ({ houseDistance }: { houseDistance: number }) => (
    <>
      <SvgXml
        xml={IconLocation()}
        width={16}
        height={16}
        style={styles.iconMargin}
      />
      <Text style={styles.miles}>{formatMiles(houseDistance)} miles</Text>
      <SvgXml
        xml={IconEllipse(colors.twColors.text.darkGray, 5, 5)}
        style={styles.iconEllipseMargin}
      />
    </>
  ),
);

// ---------- Main Component ----------

const RequestItem = ({
  item,
  isCheck = false,
  isFocused = false,
  onClickItem,
}: RequestItemProps) => {
  const { t } = useAppTranslation();
  const hasBonus = item.bonusAmount != null && item.bonusAmount > 0;

  const location = useMemo(
    () => `${item?.state ?? ''}, ${item?.street ?? ''}, ${item?.city ?? ''}`,
    [item?.state, item?.street, item?.city],
  );

  const startTime = useMemo(
    () =>
      item?.estStartDate
        ? dayjs(item.estStartDate).format(FORMAT_TIME_CLIENT_JOB_START)
        : '',
    [item?.estStartDate],
  );

  return (
    <View style={styles.rootContainer}>
      {/* Top section — lot info with colored background */}
      <Button
        style={[
          styles.requestContainer,
          isCheck || isFocused ? styles.bgMainColor : styles.defaultBackground,
        ]}
        onPress={onClickItem}
      >
        {hasBonus && (
          <BonusSection
            amount={item.amount}
            bonusAmount={item.bonusAmount!}
            isCheck={isCheck}
          />
        )}

        <View style={styles.lotInfoContainer}>
          <View style={styles.checkContainer}>
            <CheckBox isCheck={isCheck} onPress={onClickItem} />
            <Text
              style={[
                styles.txtColorLot,
                isCheck ? styles.textWhite : styles.textBlack,
              ]}
            >
              {t('LOT_NUMBER')}:{' '}
              <Text style={styles.boldText}>{item.lotNumber}</Text>
            </Text>
          </View>
          <Text style={styles.price}>{formatCurrency(item.totalAmount)}</Text>
        </View>
      </Button>

      {/* Bottom section — company & address info */}
      <View style={styles.infoContainer}>
        <Text numberOfLines={2} style={styles.txtActivityName}>
          {item.companyName} - {item.companyRoleName || 'N/A'}
        </Text>

        <View style={styles.addressContainer}>
          <Image source={defaultJob} style={styles.img} resizeMode="contain" />
          <View style={styles.flex1}>
            <Text numberOfLines={2} style={styles.location}>
              {location}
            </Text>
            <View style={styles.rowCenter}>
              {item.houseDistance > 0 && (
                <DistanceInfo houseDistance={item.houseDistance} />
              )}
              <SvgXml
                xml={IconClock()}
                width={16}
                height={16}
                style={styles.iconMargin}
              />
              <Text style={styles.font12}>
                {t('EST_START')}: <Text style={styles.miles}>{startTime}</Text>
              </Text>
            </View>
          </View>
        </View>
      </View>
    </View>
  );
};

