import React from 'react';
import { View } from 'react-native';
import { Button, Text } from 'tradewize-component';
import { styles } from '../styles';
import { colors } from '../../../../../theme';
import { globalStyles } from '../../../../../styles';
import {
  getJobStatusDisplayInfo,
  calculateInstallationProgress,
} from '../../../../../helper/myJob.helper';
import {
  ActivityTypeEnum,
  DeliveryStatus,
  JobCategoryEnum,
  JobStartTabStatus,
  UserRoleEnum,
  JobStatusData,
} from '../../../../../types/myJobs.types';
import { useAppTranslation } from '../../../../../hooks/useAppTranslation';
import { NavigationService } from '../../../../../services/NavigationService';
import { SCREEN_ENUM } from '../../../../../types/global';

interface JobStatusProps {
  jobStatusData: JobStatusData;
  jumpTo?: JobStartTabStatus;
}

export default function JobStatus({ jobStatusData, jumpTo }: JobStatusProps) {
  const { t } = useAppTranslation();

  const handleProgressPress = () => {
    NavigationService.navigate(SCREEN_ENUM.InstallationProgressScreen, {
      scheduleActivityId: jobStatusData?.scheduleActivityId,
      roleType: jobStatusData?.roleType,
    });
  };

  // Helper data from jobStatusData
  const jobReadyInfo = getJobStatusDisplayInfo({
    actEnd: jobStatusData.jobReadyActEnd,
  });

  const deliveryInfo = getJobStatusDisplayInfo({
    estStart: jobStatusData.deliveryEstStart,
    actStart: jobStatusData.deliveryActStart,
    actEnd: jobStatusData.deliveryActEnd,
  });

  const installationInfo = getJobStatusDisplayInfo({
    actStart: jobStatusData.installationActStart,
  });

  const qIInfo = getJobStatusDisplayInfo({
    estStart: jobStatusData.qiEstStart,
  });

  // Installation progress
  const installationProgress = calculateInstallationProgress(
    jobStatusData.currentSqftPercent ?? 0,
  );
  const progressValue = parseFloat(installationProgress.replace('%', ''));

  // Helper to check if roleType is LEADER
  const isLeader = jobStatusData.roleType === UserRoleEnum.LEADER;

  // Delivery: hide entire row if LaborSKUOnly (matches old project)
  const isHideMaterials =
    jobStatusData.jobCategory === JobCategoryEnum.LABOR_SKU_ONLY;

  // Disabled when role is INSPECTOR (matches old: disabled={!isShowProjectReadyChecklist})
  const isInspector = jobStatusData.roleType === UserRoleEnum.INSPECTOR;
  return (
    <View style={styles.jobStatusWrapper}>
      <View style={styles.jobStatusBox}>
        {/* Ready Checklist */}
        <Button
          style={[styles.jobStatusRow, globalStyles.btnTrazeStyle]}
          disabled={isInspector}
          onPress={() => {
            if (jobStatusData.scheduleActivityId) {
              NavigationService.navigate(SCREEN_ENUM.JobReadyChecklistScreen, {
                scheduleActivityId: jobStatusData.scheduleActivityId,
                workOrderId: jobStatusData.workOrderId,
              });
            }
          }}
        >
          <Text style={[styles.jobStatusText, isLeader && styles.underline]}>
            {t('READY_CHECKLIST')}
          </Text>
          <Text style={[styles.myJobInfo, { color: jobReadyInfo?.color }]}>
            {jobReadyInfo?.date || ''}
          </Text>
        </Button>

        {/* Delivery — hidden when LaborSKUOnly (matches old project) */}
        {!isHideMaterials && (
          <View style={styles.jobStatusRow}>
            <Button
              style={globalStyles.btnTrazeStyle}
              disabled={isInspector}
              onPress={() => {
                NavigationService.navigate(
                  SCREEN_ENUM.MaterialDeliveredScreen,
                  { workOrderId: jobStatusData.pODeliveryId },
                );
              }}
            >
              <Text
                style={[styles.jobStatusText, isLeader && styles.underline]}
              >
                {t('DELIVERY')}
              </Text>
            </Button>
            {jobStatusData.deliveryStatus ===
              DeliveryStatus?.OUT_FOR_DELIVERY && isLeader ? (
              <Button
                style={globalStyles.btnTrazeStyle}
                onPress={() => {
                  NavigationService.navigate('TrackingDriver', {
                    job: jobStatusData,
                  });
                }}
              >
                <Text style={[styles.myJobInfo, styles.btnOnDelivery]}>
                  {jobStatusData.deliveryStatusName || ''}
                </Text>
              </Button>
            ) : (
              <Text style={[styles.myJobInfo, { color: deliveryInfo?.color }]}>
                {deliveryInfo?.date || ''}
              </Text>
            )}
          </View>
        )}

        {/* Installation */}
        <View style={styles.jobStatusRow}>
          <Text style={styles.jobStatusText}>{t('INSTALLATION')}</Text>
          <Text style={[styles.myJobInfo, { color: installationInfo?.color }]}>
            {installationInfo?.date || ''}
          </Text>
        </View>

        {/* QI Checklist */}
        <View style={styles.jobStatusRow}>
          {jobStatusData.activityTypeEnum !== ActivityTypeEnum?.INSPECTION &&
            (jobStatusData.qiIncompleteItems === null ||
            jobStatusData.qiIncompleteItems === undefined ||
            jobStatusData.qiIncompleteItems === 0 ? (
              <>
                <Text style={[styles.jobStatusText, styles.underline]}>
                  {t('QI_CHECKLIST')}
                </Text>
                <Text style={[styles.myJobInfo, { color: qIInfo?.color }]}>
                  {qIInfo?.date || ''}
                </Text>
              </>
            ) : (
              <Button
                style={globalStyles.btnTrazeStyle}
                disabled={!isLeader}
                onPress={() => {
                  if (isLeader && jobStatusData.scheduleActivityId) {
                    NavigationService.navigate(SCREEN_ENUM.QIInspectionScreen, {
                      taskId: jobStatusData.scheduleActivityId,
                      isInspector: false,
                      qiIncompleteItems: jobStatusData.qiIncompleteItems,
                    });
                  }
                }}
              >
                <Text
                  style={[
                    styles.jobStatusText,
                    isLeader ? styles.underline : undefined,
                    jobStatusData.qiIncompleteItems > 0
                      ? { color: colors.alertColorError }
                      : undefined,
                  ]}
                >
                  {t('QUALITY_INSPECTION')}: {jobStatusData.qiIncompleteItems}{' '}
                  {t('INCOMPLETE_ITEMS')}
                </Text>
              </Button>
            ))}
        </View>

        {/* Installation Progress */}
        {jumpTo === JobStartTabStatus.IN_PROGRESS && (
          <>
            <Button
              variant="ghost"
              style={[styles.jobStatusRow, styles.installationProgressRow]}
              onPress={handleProgressPress}
            >
              <Text style={styles.jobStatusText}>
                {t('INSTALLATION_PROGRESS')}
              </Text>
              <Text
                style={[
                  styles.myJobInfo,
                  styles.underline,
                  { color: colors.black },
                ]}
              >
                {installationProgress}
              </Text>
            </Button>
            <View style={styles.installationProgressContainer}>
              <View style={styles.installationProgressBarContainer}>
                <View
                  style={[
                    styles.installationProgressBarFill,
                    { width: `${progressValue}%` },
                  ]}
                />
              </View>
            </View>
          </>
        )}
      </View>
      <View style={styles.jobStatusLabel}>
        <Text style={styles.headerLabel}>{t('JOB_STATUS')}</Text>
      </View>
    </View>
  );
}
