import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { ScrollView } from 'react-native';
import { useDispatch, useSelector } from 'react-redux';
import { useRoute } from '@react-navigation/native';
import { RootState } from '../../../../Auth/src/redux/store/types';
import { actionJobDetail } from '../../../../Auth/src/redux/features/jobDetail/actions';
import { NavigationService } from '../../services/NavigationService';
import { formatDate } from '../../helper/myJob.helper';

interface RouteParams {
  workOrderId: string;
}

const useMaterialDelivered = () => {
  const route = useRoute();
  const dispatch = useDispatch();
  const scrollViewRef = useRef<ScrollView>(null);

  // Route params
  const { workOrderId } = (route.params as RouteParams) || {};

  // Redux state
  const workOrderData = useSelector(
    (state: RootState) => state.jobDetail.materialDelivered.data,
  );
  const isLoading = useSelector(
    (state: RootState) => state.jobDetail.materialDelivered.isLoading,
  );
  const chatData = useSelector(
    (state: RootState) => state.jobDetail.materialDeliveredChat.data,
  );

  // UI state
  const [isChatExpanded, setIsChatExpanded] = useState(false);

  // Fetch data
  const fetchData = useCallback(() => {
    if (!workOrderId) {return;}

    dispatch(actionJobDetail.getMaterialDeliveredAsync({ workOrderId }));
    dispatch(actionJobDetail.getMaterialDeliveredChatAsync({ workOrderId }));
  }, [dispatch, workOrderId]);

  useEffect(() => {
    fetchData();

    return () => {
      dispatch(actionJobDetail.clearMaterialDelivered());
    };
  }, [fetchData, dispatch]);

  // Handlers
  const handleGoBack = useCallback(() => {
    dispatch(actionJobDetail.clearMaterialDelivered());
    NavigationService.goBack();
  }, [dispatch]);

  const toggleChat = useCallback(() => {
    setIsChatExpanded(prev => !prev);
  }, []);

  // Derived data
  const supplierName = useMemo(
    () => workOrderData?.workerInfo?.fullName || 'N/A',
    [workOrderData?.workerInfo?.fullName],
  );

  const deliveredDate = useMemo(
    () =>
      formatDate(
        workOrderData?.actualEndDate ||
          workOrderData?.actualStartDate ||
          workOrderData?.estEndDate,
      ),
    [
      workOrderData?.actualEndDate,
      workOrderData?.actualStartDate,
      workOrderData?.estEndDate,
    ],
  );

  const resolvedChatId = useMemo(
    () => (workOrderData as any)?.chatId || chatData?.id,
    [workOrderData, chatData?.id],
  );

  return {
    scrollViewRef,
    workOrderData,
    isLoading,
    isChatExpanded,
    supplierName,
    deliveredDate,
    resolvedChatId,
    handleGoBack,
    toggleChat,
  };
};

export default useMaterialDelivered;
