import React, {
  useCallback,
  useMemo,
  useRef,
  forwardRef,
  useImperativeHandle,
} from 'react';
import { View, StyleSheet, Image } from 'react-native';
import BottomSheet, {
  BottomSheetBackdrop,
  BottomSheetBackdropProps,
  BottomSheetScrollView,
} from '@gorhom/bottom-sheet';
import { Button, Text, SCREEN_HEIGHT } from 'tradewize-component';
import { colors } from '../../../../theme';
import { icPlay, playInstructionalVideos } from '../../../../assets/images';
import { useAppTranslation } from '../../../../hooks/useAppTranslation';

export interface VideoOption {
  id: string;
  title: string;
  url: {
    en: string;
    es: string;
  };
  subtitle: {
    en: string;
    es: string;
  };
}

export interface VideoSelectionModalRef {
  open: () => void;
  close: () => void;
}

interface VideoSelectionModalProps {
  onPlayVideo: (video: VideoOption) => void;
  onPlayAll: (videos: VideoOption[]) => void;
  videos: VideoOption[];
}

const VideoSelectionModal = forwardRef<
  VideoSelectionModalRef,
  VideoSelectionModalProps
>(({ onPlayVideo, onPlayAll, videos }, ref) => {
  const { t } = useAppTranslation();
  const bottomSheetRef = useRef<BottomSheet>(null);
  const snapPoints = useMemo(() => ['70%'], []);
  const bottomInset = useMemo(() => SCREEN_HEIGHT / 4, []);

  useImperativeHandle(ref, () => ({
    open: () => {
      bottomSheetRef.current?.snapToIndex(0);
    },
    close: () => {
      bottomSheetRef.current?.close();
    },
  }));

  const handleClose = useCallback(() => {
    bottomSheetRef.current?.close();
  }, []);

  const renderBackdrop = useCallback(
    (props: BottomSheetBackdropProps) => (
      <BottomSheetBackdrop
        {...props}
        disappearsOnIndex={-1}
        appearsOnIndex={0}
        opacity={0.5}
        pressBehavior="close"
      />
    ),
    [],
  );

  return (
    <BottomSheet
      ref={bottomSheetRef}
      index={-1}
      snapPoints={snapPoints}
      animateOnMount={true}
      enablePanDownToClose={true}
      enableContentPanningGesture={true}
      enableHandlePanningGesture={true}
      enableDynamicSizing={false}
      backdropComponent={renderBackdrop}
      detached={true}
      bottomInset={bottomInset}
      style={styles.sheetContainer}
      backgroundStyle={styles.sheetBackground}
    >
      <BottomSheetScrollView
        contentContainerStyle={styles.scrollContent}
        showsVerticalScrollIndicator={false}
        bounces={false}
      >
        <View style={styles.videoList}>
          {videos.map(video => (
            <Button
              variant="ghost"
              key={video.id}
              style={styles.videoItem}
              onPress={() => {
                handleClose();
                onPlayVideo(video);
              }}
            >
              <Image source={playInstructionalVideos} style={styles.playIcon} />
              <Text style={styles.videoTitle}>{video.title}</Text>
            </Button>
          ))}
        </View>
      </BottomSheetScrollView>

      <View style={styles.buttonContainer}>
        <Button
          variant="ghost"
          style={styles.closeButton}
          onPress={handleClose}
        >
          <Text style={styles.closeButtonText}>{t('CLOSE')}</Text>
        </Button>

        <Button
          variant="ghost"
          style={styles.playAllButton}
          onPress={() => {
            handleClose();
            onPlayAll(videos);
          }}
        >
          <Image source={icPlay} style={styles.playAllIcon} />
          <Text style={styles.playAllButtonText}>{t('PLAY_ALL')}</Text>
        </Button>
      </View>
    </BottomSheet>
  );
});

VideoSelectionModal.displayName = 'VideoSelectionModal';

export default VideoSelectionModal;

