import { PhotoAttachment, ProgressHistoryItem } from './types';

export const delay = (ms: number) =>
  new Promise((resolve: any) => setTimeout(resolve, ms));

export function getRandomNumbers(count: number): number[] {
  const result: number[] = [];
  for (let i = 0; i < count; i++) {
    result.push(Math.floor(Math.random() * 101));
  }
  return result.sort((a, b) => a - b);
}

export const formatDate = (dateString: string) => {
  try {
    const date = new Date(dateString);
    return date.toLocaleDateString('en-US', {
      month: 'short',
      day: 'numeric',
      hour: '2-digit',
      minute: '2-digit',
    });
  } catch (error) {
    return dateString;
  }
};

export const isImageFile = (fileExtension: string) => {
  const imageExtensions = ['jpg', 'jpeg', 'png', 'gif', 'webp', 'bmp'];
  return imageExtensions.includes(fileExtension?.toLowerCase() || '');
};

export const isToday = (dateString: string) => {
  try {
    const date = new Date(dateString);
    const today = new Date();
    return (
      date.getFullYear() === today.getFullYear() &&
      date.getMonth() === today.getMonth() &&
      date.getDate() === today.getDate()
    );
  } catch (error) {
    return false;
  }
};

export const checkIfSubmittedToday = (
  histories: ProgressHistoryItem[],
): boolean => {
  if (!histories || histories.length === 0) return false;
  return histories.some(item => isToday(item.updatedAt));
};

export const getTodaySqftFromHistory = (
  histories: ProgressHistoryItem[],
): string | null => {
  if (!histories || histories.length === 0) return null;

  const todayHistories = histories.filter(item => isToday(item.updatedAt));

  if (todayHistories.length === 0) return null;

  todayHistories.sort((a, b) => {
    const dateA = new Date(a.updatedAt).getTime();
    const dateB = new Date(b.updatedAt).getTime();
    return dateB - dateA;
  });

  return todayHistories[0].sqft?.toString() || null;
};

export const getLatestTodayEntry = (
  histories: ProgressHistoryItem[],
): ProgressHistoryItem | null => {
  if (!histories || histories.length === 0) return null;

  const todayHistories = histories.filter(item => isToday(item.updatedAt));

  if (todayHistories.length === 0) return null;

  todayHistories.sort((a, b) => {
    const dateA = new Date(a.updatedAt).getTime();
    const dateB = new Date(b.updatedAt).getTime();
    return dateB - dateA;
  });

  return todayHistories[0];
};

export const sumArea = (data: PhotoAttachment[]) => {
  return Object.values(data).reduce((total, item) => {
    return total + Number(item.area);
  }, 0);
};
