import React, { useCallback, useState } from 'react';
import { TouchableOpacity, View, Pressable } from 'react-native';
import { Text, SCREEN_WIDTH } from 'tradewize-component';
import { SvgXml } from 'react-native-svg';
import { colors } from '../../../theme';
import { IconComment } from '../../../assets/svg';
import { styles } from '../styles';
import type { VPOChecklistItem, Response } from '../../../types/jobDetail.type';
import {
  FileThumbnail,
  FileInfo,
  FileViewer,
} from '../../../components/FileViewer';

// ============================================================================
// Types
// ============================================================================

export interface VPOItemCardProps {
  item: VPOChecklistItem;
  onQuantityPress: (itemId: string, maxQuantity: number) => void;
  onCommentPress: (item: VPOChecklistItem) => void;
  getInitialValue: (item: VPOChecklistItem) => string | undefined;
  t: (key: string) => string;
}

// ============================================================================
// Component
// ============================================================================

const VPOItemCard: React.FC<VPOItemCardProps> = React.memo(
  ({ item, onQuantityPress, onCommentPress, getInitialValue, t }) => {
    const quantityLabel = getInitialValue(item);
    const [selectedFile, setSelectedFile] = useState<FileInfo | null>(null);

    const handleQuantityPress = useCallback(() => {
      onQuantityPress(item.id, item.missingQuantity);
    }, [item.id, item.missingQuantity, onQuantityPress]);

    const handleCommentPress = useCallback(() => {
      onCommentPress(item);
    }, [item, onCommentPress]);

    const handleMediaPress = useCallback((file: FileInfo) => {
      setSelectedFile(file);
    }, []);

    const handleCloseViewer = useCallback(() => {
      setSelectedFile(null);
    }, []);

    return (
      <View style={styles.materialItemContainer}>
        <View style={styles.materialItem}>
          <View style={styles.materialInfo}>
            <Text style={styles.materialName} numberOfLines={2}>
              {item.materialName}
            </Text>
            <Text style={styles.materialDetails}>
              <Text style={styles.materialDetailsBold}>
                {t('QUANTITY')}: {item.missingQuantity}
              </Text>
              {` - ${t('COLOR')}: ${item.colorName}`}
            </Text>
            <Text style={styles.materialDetails}>
              {t('SIZE')}: {item.size || '-'} - U/M: {item.unitTypeName || '-'}
            </Text>
          </View>

          {/* Comment Icon - top right */}
          <Pressable
            style={styles.commentButton}
            onPress={handleCommentPress}
            hitSlop={8}
          >
            <SvgXml
              xml={IconComment(colors.mainColorPrimary)}
              width={SCREEN_WIDTH * 0.06}
              height={SCREEN_WIDTH * 0.06}
            />
          </Pressable>
        </View>

        {/* Responses list */}
        {item.response?.length > 0 && (
          <View style={styles.responsesContainer}>
            {item.response.map(
              (responseItem: Response, _responseIndex: number) => (
                <View
                  key={responseItem.responseId || _responseIndex}
                  style={styles.responseItem}
                >
                  <View style={styles.responseLeftSection}>
                    <Text style={styles.responseAuthor}>
                      {responseItem.createdName}
                    </Text>
                  </View>
                  <View style={styles.responseRightSection}>
                    {responseItem.comment && (
                      <Text style={styles.commentText}>
                        {responseItem.comment}
                      </Text>
                    )}
                    <View style={styles.mediaContainer}>
                      {responseItem.fileEntities?.map(
                        (media: any, idx: number) => {
                          const fileInfo: FileInfo = {
                            ...media,
                            uri: media.url || media.fileUrl,
                            type:
                              media.fileExtension === '.mp4' ? 'video' : 'file',
                            name: media.fileName || media.name,
                          };
                          return (
                            <FileThumbnail
                              key={`${media.fileId || idx}`}
                              file={fileInfo}
                              size="small"
                              readOnly
                              onPress={() => handleMediaPress(fileInfo)}
                            />
                          );
                        },
                      )}
                    </View>
                  </View>
                </View>
              ),
            )}
          </View>
        )}

        {/* Received Quantity Selector */}
        <TouchableOpacity
          style={styles.toggleContainer}
          onPress={handleQuantityPress}
          activeOpacity={0.7}
        >
          <View style={styles.toggleWrapper}>
            <Text style={styles.selectorLabel}>
              {t('RECEIVED_NUMBER')}
              <Text style={styles.selectorLabelRequired}> *</Text>
            </Text>
            <View style={styles.selectedValueContainer}>
              <Text
                style={
                  quantityLabel
                    ? styles.selectedValueText
                    : styles.placeholderText
                }
              >
                {quantityLabel ?? t('PLEASE_SELECT_RECEIVED_NUMBER')}
              </Text>
            </View>
          </View>
        </TouchableOpacity>

        {/* Missing quantity display */}
        {item.quantityMissing2 !== null &&
          item.quantityMissing2 !== 0 &&
          item.quantityMissing2 !== undefined && (
            <View style={styles.missingContainer}>
              <Text style={styles.missingText}>
                {t('MISSING')}: {item.quantityMissing2}
              </Text>
            </View>
          )}

        {/* File Viewer */}
        {selectedFile && (
          <FileViewer
            visible={!!selectedFile}
            onClose={handleCloseViewer}
            file={selectedFile}
          />
        )}
      </View>
    );
  },
);

export default VPOItemCard;
