import React from 'react';
import { View, TouchableOpacity, StyleSheet } from 'react-native';
import { Text } from 'tradewize-component';
import { colors } from '../../../theme';
import {
  CrewParticipant,
  ParticipantStatus,
} from '../../../types/jobDetail.type';
import { SvgXml } from 'react-native-svg';
import { IconArrowRight, IconCheck } from '../../../assets/svg';

interface ParticipantItemProps {
  participant: CrewParticipant;
  statusColor: string;
  statusText: string;
  progress: number;
  onPress: (participant: CrewParticipant) => void;
}

const ParticipantItem: React.FC<ParticipantItemProps> = ({
  participant,
  statusColor,
  statusText,
  progress,
  onPress,
}) => {
  const isCompleted = participant.status === ParticipantStatus.Completed;
  const progressPercent = Math.round(progress);

  return (
    <TouchableOpacity
      style={styles.container}
      onPress={() => onPress(participant)}
      activeOpacity={0.7}
    >
      {/* Header: Title and Role Badge */}
      <View style={styles.header}>
        <Text style={styles.title} numberOfLines={1}>
          {participant.workerName || 'Unassigned'}
        </Text>
        <View
          style={[
            styles.roleBadge,
            { backgroundColor: colors.mainColorQuaternary },
          ]}
        >
          <Text style={[styles.roleText, { color: colors.mainColorPrimary }]}>
            {participant.companyRoleName}
          </Text>
        </View>
      </View>

      {/* Company Name */}
      <Text style={styles.companyName}>{participant.companyName}</Text>

      {/* Status */}
      <Text style={[styles.statusText, { color: statusColor }]}>
        {statusText}
      </Text>

      {/* Progress Bar */}
      <View style={styles.progressContainer}>
        <View style={styles.progressBarBackground}>
          <View
            style={[
              styles.progressBarFill,
              {
                width: `${progressPercent}%`,
                backgroundColor: isCompleted
                  ? colors.alertColorSuccess
                  : colors.mainColorPrimary,
              },
            ]}
          />
        </View>
        <Text style={styles.progressText}>
          {participant.checklistChecked}/{participant.checklistTotal}
        </Text>
      </View>

      {/* Arrow */}
      <View style={styles.arrowContainer}>
        <SvgXml
          xml={IconArrowRight(colors.mainColorPrimary)}
          width={16}
          height={16}
        />
      </View>
    </TouchableOpacity>
  );
};

const styles = StyleSheet.create({
  container: {
    backgroundColor: colors.white,
    borderRadius: 12,
    padding: 16,
    marginBottom: 12,
    shadowColor: '#000',
    shadowOffset: { width: 0, height: 2 },
    shadowOpacity: 0.05,
    shadowRadius: 4,
    elevation: 2,
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: 4,
  },
  title: {
    fontSize: 16,
    fontWeight: '600',
    color: colors.grayScale100,
    flex: 1,
    marginRight: 8,
  },
  roleBadge: {
    paddingHorizontal: 10,
    paddingVertical: 4,
    borderRadius: 6,
  },
  roleText: {
    fontSize: 12,
    fontWeight: '500',
  },
  companyName: {
    fontSize: 14,
    color: colors.grayScale70,
    marginBottom: 8,
  },
  statusText: {
    fontSize: 14,
    fontWeight: '500',
    marginBottom: 12,
  },
  progressContainer: {
    flexDirection: 'row',
    alignItems: 'center',
  },
  progressBarBackground: {
    flex: 1,
    height: 6,
    backgroundColor: '#E5E7EB',
    borderRadius: 3,
    overflow: 'hidden',
    marginRight: 12,
  },
  progressBarFill: {
    height: '100%',
    borderRadius: 3,
  },
  progressText: {
    fontSize: 12,
    color: colors.grayScale70,
    minWidth: 30,
    textAlign: 'right',
  },
  arrowContainer: {
    position: 'absolute',
    right: 16,
    top: '55%',
    // transform: [{ translateY: -10 }],
  },
  arrow: {
    fontSize: 18,
    color: colors.grayScale50,
  },
});

export default ParticipantItem;
